quests[86458] = { id = 86458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Song for Our Future", description = "There is a site, Eco-Dome: Al'dani, which I have kept hidden. It is built on the remains of one of our most sacred places with a powerful connection to K'aresh. It is the site of our greatest triumph of the project. This is the place where we can take the Worldsoul's essence so it can survive.\n\nThis is also the eco-dome where Soul-Scribe and her Wastelanders are attacking.\n\nClear the way for me one last time, {name}. For K'aresh to survive, we need both the dome and Soul-Scribe intact.", progress = "We must make Soul-Scribe see reason. We must prevent her oath to Salhadaar from dooming K'aresh.", completion = "What transpired here will echo for years to come. The change will not happen within a day, a week, or even months. But with hope rekindled, we will get there, and we will be united once again.\n\nYou have saved us all, champion.", objectives = "Defeat Soul-Scribe within Eco-Dome: Al'dani.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86461] = { id = 86461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Curiosity: Combat", description = "<You hold the curio and discover a shimmering glow emanating from it. This looks important. The Explorers' League would be interested in this.>", objectives = "Use and equip a Combat Curio to Brann Bronzebeard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
