quests[86469] = { id = 86469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Stromgarde Tour", objectives = "Deal with 1 Marran Supporters in Stromgarde.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86470] = { id = 86470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fearin's Version", description = "I need someone to deliver these requests to people around the city. We've been shorthanded and I haven't gotten around to distributing this bunch.\n\nAs my newest deputy, this responsibility is now yours!\n\nMost of these are simple and straightforward. Requests for supplies and such for the Stromic army.\n\nJoseph is another matter. He's been inciting the populace with inflammatory rhetoric. He needs to stop or we will have to arrest him. We can't afford another riot breaking out right now.", objectives = "Deliver Brewston's requests to people in Stromgarde.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86476] = { id = 86476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldsoul Memory: Early Cartel Wars" }
quests[86477] = { id = 86477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldsoul Memory: Kaja'mite Contact" }
quests[86479] = { id = 86479, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - 11.0 The War Within - Raid Finder - 1st" }
