quests[86481] = { id = 86481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[86482] = { id = 86482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lifeline", description = "<The snapdragon barely moves as you approach. It is clearly weak and seems much smaller than it should be. \n\nPerhaps Zexel Fingersnap has something for sale that could help get it back up on its feet?>", progress = "<The small snapdragon looks wearily at you with dull eyes.>", completion = "<The small snapdragon voraciously tears into the morsel. It seems to be energized by both the meat and the caffeinated Kaja'Cola the meat was soaked in.\n\nIt looks up at you with gratitude in its eyes. \n\nIt will remember you.>", objectives = "Talk to Zexel Fingersnap.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86483] = { id = 86483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snap To It", description = "<The snapdragon seems to recognize you as you approach, its ear fins wiggling with anticipation. \n\nNot only has it grown bigger overnight, but its scales have changed to a seaweed-green color similar to the Kaja'cola-braised meat you fed it.\n\nBetween it's talons lie morsels of meaty rations it has stolen from nearby invading forces. The snapdragon looks at you expectantly.\n\nPerhaps you can bring it more meaty rations by slaying the invading forces on the island.>", progress = "<The snapdragon paws the ground and then looks at you expectantly. Its eyes glitter with intelligence.>", completion = "<The snapdragon perks up as you approach and sniffs the air as if to check to see if you've brought it food. \n\nThe second it sees the rations in your hand it begins snapping it's jaws in anticipation of a tasty meal. \n\nWith a newly full belly the snapdragon runt lays down to rest but peers up at you, as if hoping you will return tomorrow.>", objectives = "Find 5 Meaty Rations from the invading forces: Pirates, Naga or Vrykul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86484] = { id = 86484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temper Like A Tempest", description = "<The snapdragon seems to recognize you as you approach, its ear fins wiggling with anticipation. \n\nNot only has it grown bigger overnight, but its scales have changed color from the meat you fed it yesterday.\n\nBetween it's talons lie the remains of a sea creature from the last Seafury Tempest. The snapdragon looks at you expectantly.\n\nPerhaps by venturing into the Seafury Tempest and slaying creatures there you can bring it more meat.>", progress = "<The snapdragon paws the ground, then looks at you expectantly. Its eyes glitter with intelligence and hunger.>", completion = "<Upon seeing the meat you have brought it, the snapdragon clicks its jaw hungrily. The second you set down the meat it tears into it veraciously finishing the meal in seconds.\n\nIt looks up at you with newfound respect in it's eyes; after all, you have slain mighty creatures to bring it this meal.>", objectives = "Speak to Suzie Boltwrench to enter the Seafury Tempest and slay creatures to obtain Storm-infused Mystery Meat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86485] = { id = 86485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Loyal Friend", description = "<The snapdragon seems to recognize you as you approach, its ear fins wiggling with anticipation.\n\nIts massive, lithe body unfurls as it stands before you as a fully grown adult. It stares you down, clacking it's massive jaw gently as if it's deciding something.\n\nIt seems to wait for you to make the first move.>", progress = "<The snapdragon hisses and wiggles it's ear fins, looking impressed.>", completion = "<The snapdragon bows its head to you as a sign of respect. It seems to be grateful for all you have done for it.\n\nIt will now accept you as its rider.>", objectives = "Speak to the snapdragon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86486] = { id = 86486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hungry, Hungry Snapdragon", description = "<The snapdragon seems to recognize you as you approach. Its ear fins wiggle with anticipation. \n\nIt is hungry again and looks at you expectantly. It seems to want meat and doesn't seem to care where it comes from.>", progress = "<The snapdragon stirs as you approach, its unnaturally-intelligent eyes scanning you. \n\nClearly it hopes you have brought it a meal.>", completion = "<The snapdragon barely waits for you to drop the rations before voraciously devouring them. Clearly it was hungry.\n\nOnce it finishes, it looks contented and drowsy. You realize it won't be this way for long. Perhaps you should try to feed it again tomorrow.>", objectives = "Collect 8 Mystery Meat Snacks by killing creatures around the Siren Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86491] = { id = 86491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dastardly Duos! It's on!", description = "Hello, fight fans. The world's meanest villains are teamed up and back for revenge! They have returned, this time as Dastardly Duos!\n\nMeet me in Dornogal, at the foot of Contender's Gate and sign up to face the Dastardly Duos. Beat down these bosses one more time. Relive the dream!\n\n-Vinnie Sweets", completion = "There you are. Now let's make some money!", objectives = "Speak with Vinnie Sweets in Dornogal near Contender's Gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86493] = { id = 86493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - Timewalking \"Heroic\" Random - 1st", objectives = "You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86494] = { id = 86494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - Timewalking \"Heroic\" Random - Nth", objectives = "You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86495] = { id = 86495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Reshii Ribbon", description = "During the Devouring War, I witnessed the horrific results of the All-Devouring's presence. A mortal being cannot approach him at the manaforge. He is the entropy of the end, and you are just flesh.\n\nXal'atath knows rituals from across the Great Dark Beyond. With the power of the Reshii Ribbons, she was able to transform the K'areshi so they could withstand Dimensius.\n\nAlleria will not like this plan. You must convince her!", progress = "Every moment spent debating or arguing is a moment closer to Dimensius emerging.", completion = "She agreed?\n\nAlleria listens to you, my champion. You are indeed our savior.", objectives = "Convince Alleria to let Xal'atath perform the ritual of transformation on you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86496] = { id = 86496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Ordered Design", description = "<Bargus holds up a tiny splinter of golden crystal.>\n\nMuch like the radiant remnants found by the Arathi within Hallowfall, the Siren Crystal appears to be effecting the surrounding geological matrix of the island.\n\nUnlike our goblin compatriots, I don't recommend harvesting the larger shards we've seen around the isle, lest we disturb the fragile caverns beneath us or offend the Arathi. \n\nBut these tiny splinters are worth investigating.\n\nBring me a sizable portion. For... experimental purposes.", progress = "Have you found more splinters of the Siren Crystal? I think I may be able to create something useful with them.", completion = "<Bargus spreads the rubble onto his anvil and nods firmly.>\n\nI will begin research on this new material immediately! You have my gratitude, {name}.\n\nYou are welcome to help yourself to the newest sets of armaments I have recently forged. \n\nThey were slated for delivery to the Awakening Machine, but since they seem like the perfect size for you, you are welcome to sample my work.", objectives = "Collect 50 crystal-splintered rubble.\n\nThe crystal-splintered rubble can only be looted from creatures on the Siren Isle during the Seafury Tempest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86503] = { id = 86503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Who are the Dastardly Duos?", description = "Great question! Here's how to find out: Talk to Xyggie Marou and sign up to fight the Dastardly Duos.\n\nAnd because you're new to this, let me give you a list of \"Dastardly\" tasks to do while you're in there!\n\nGood luck! Maybe I'll see you on the other side.", progress = "Speak with Xyggie Marou, do my tasks, and beat those Dastardly Duos!", completion = "I saw your fight, good stuff. Here's your prize purse. Pleasure doing business.\n\nFeel free to sign up again. I'll remember to not bet against you next time.", objectives = "Beat the Dastardly Duos while finishing Vinnie's \"Dastardly\" tasks, then speak with Vinnie Sweets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86509] = { id = 86509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Friend or Fiend", description = "Despite that spirited display, I'm inclined to help you. After all, what's a little violence between friends? \n\nAnd since we're friends, I'll let you in on a secret: shutting down the storm is only possible from inside the Nexus-Points. Of course you can't just walk in--you need the Mantle of Predation.\n\n<Decimus seems to savor the words.>\n\nDo I have your attention? Let's shake the dust off and discuss this somewhere... civilized. Meet me at my estate.", completion = "Guests are a rare treat for a domanaar. Especially ones that come of their own accord.", objectives = "Travel to the Howling Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86510] = { id = 86510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Domus Penumbra", description = "It seems we all wish to stop the Voidstorm. Common ground--a rare thing here. I'll even tell you how to do it, and all I ask in return is for you to let me enjoy the show.\n\nBut you must be tired. Show yourself around, and help yourself to the amenities. Then we will continue our discussion.\n\nDon't take too long. There is much to see, and the storm rages on.", completion = "Comfortable? So nice to see someone appreciate my hospitality.\n\nNow I suppose we must discuss business before your glowing friend has another tantrum.", objectives = "Establish your base at the Howling Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86511] = { id = 86511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Edge of the Abyss", description = "I don't trust Decimus any more than the rest of the beasts here. I do trust that they only serve themself. Seems having Xal'atath as a master isn't to their taste. We can turn one foe against another. Even Lothraxion would agree if he weren't so stubborn.\n\nIf this Mantle of Predation will let us stop the storm, then it's our best shot. A troop of ren'dorei have been scouting the Obscurion Citadel. We'll meet with them and see what they've learned.", progress = "I've avoided this place until now. The howls and the stench are carried on the wind like a warning.", completion = "I don't like dividing our forces. Not when this much is at stake.\n\nLet's not rush in like Lothraxion. See what Decimus knows. I'd rather not hunt a domanaar unprepared.", objectives = "Meet the ren'dorei scouts near the Obscurion Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86512] = { id = 86512, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Harvest", description = "Two sigils--you'll need both to open Terminas's vault and claim the Mantle.\n\nThe first belongs to Torentia, petty ruler of this sad trench. Too ambitious for Terminas to bring her into his inner circle, too cowardly to strike out on her own. So here she cowers behind an unbreakable shield of Void.\n\nShe's terrified of losing her already meager holdings. What a pity. Slaughter your way through the trench. The potential emergence of a new apex predator is something she won't ignore.", progress = "Do you feel the hunger of this place? No wonder the Void came here.", completion = "Do you sense it? Every beast here either fears you or wants to kill you. Even their mistress cannot ignore you now.", objectives = "Slay foes to attract Torentia's attention.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86513] = { id = 86513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Face the Tide", progress = "Even if we fail--Light forfend--at least we'll have struck a blow.", completion = "This is what my mother has battled on her own for all these years? I won't let her shoulder that burden alone anymore.", objectives = "Disrupt Obscurion Citadel forces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86514] = { id = 86514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lady of the Pit", description = "For all their power, these domanaar still behave like beasts. That's good for us. Wolves try to avoid each other, but if one threatens another's territory, they'll fight to the death. \n\nBy now, I think you've more than proven that you're a threat. Torentia can't back down if you challenge her--it would go against her nature.\n\nSo take the fight to her, slay her, and claim her sigil.", progress = "Have you claimed Torentia's sigil?", completion = "I've never known Lothraxion to be careless like this. Throwing lives away, charging in blind--doesn't he know he's not leading an army here? \n\nAt least you've done your part. Let's try to salvage the mission.", objectives = "Challenge Torentia and claim her sigil to access the vault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86515] = { id = 86515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hollow Hunger", description = "Alleria's judgement is clouded. She's spent too much time steeped in Void. I've prosecuted campaigns across the cosmos. Casualties are inevitable. I could not command if the loss of every soldier broke my will.\n\nWe have the information we need: the location of the sigil bearer. The fiends whisper of a domanaar named Severum. Slay him and take his sigil, then we can be rid of this place.", progress = "Would that we could put every voidspawn to the sword.", completion = "Well done. Soon we'll have the Mantle of Predation and no longer need Decimus.\n\nDo not mistake their usefulness for allegiance as Alleria has.", objectives = "Slay Severum and claim his sigil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86516] = { id = 86516, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Become Prey", description = "Lothraxion's acting like we have an army, but a single ultradon will tear through us if we're caught off guard. We need to be smarter.\n\nI've watched the beasts of this world: studied them, tracked them, killed them. They prey on weakness, and cull their own kind at the first sign of frailty. \n\nHarvest carrion essence from the carcasses around the citadel. Use it to mark ultradons. Other beasts will pounce, thinking they're wounded or dying. Let them tear each other apart, then clean up what's left.", progress = "These creatures operate on base instinct. We can exploit that.", completion = "Good hunting. With the ultradons dead, we may just be able to get out of here alive.", objectives = "Slay Slavering Ultradons by marking them with Carrion Essence.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86517] = { id = 86517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vanished in the Void", description = "\"Acceptable losses.\" I hope I never find it that easy to dismiss the deaths of friends and comrades. What use is the Light if it leaves us as callous as our enemies?\n\nSideras was nearly killed. Luckily, he escaped through a rift. Riftblade Maella led the others in a fighting retreat. Find her. Hopefully they stuck together.\n\nI can't leave Sideras--not until he's stable.", progress = "Lothraxion should know better than this.", completion = "This isn't right. Hieron didn't come here to die. The Light should protect people, not lead them to their deaths.\n\n<Arator seems lost in thought.>\n\nThank you. I'll make sure to give his journal to the others.", objectives = "Find the missing void elves.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86518] = { id = 86518, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mantle of Predation", description = "Let's move quickly. We need to steal the Mantle before Terminas returns and before Lothraxion does something rash. \n\nI understand this place grates on him, but he should know to trust my instincts. I thought we'd fought together long enough to earn that.\n\nLet's end this. Ready when you are.", completion = "Are you alright? I must have missed something. Why did Decimus bother helping us at all? They could have betrayed us at any time. It doesn't make any sense...", objectives = "Steal the Mantle of Predation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86519] = { id = 86519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abyssus, Abyssum", description = "I don't see Decimus. For all their glee at handing us over, I'd expect they'd want to watch the fight. What could be more important to a domanaar than enjoying a battle?\n\n<Alleria nocks another arrow.>\n\nAnswers can wait. Right now we need to survive.", completion = "Lothraxion's going to tear the Nexus-Points apart, even if it costs us Silvermoon!", objectives = "Conquer Terminas's arena.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86520] = { id = 86520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunt the Light", completion = "He's already here. We have to stop him.", objectives = "Meet Alleria Windrunner at Nexus-Point Xenas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86521] = { id = 86521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nexus-Point Xenas: Eclipse", description = "If he destroys the Nexus-Point, everyone we're fighting for could perish. I'll try to talk him down, but if I can't, if I have to...\n\n<Alleria's face clouds.>\n\nNo hesitation. We end this, one way or another.", completion = "It's over. We can breathe, if only for a moment.", objectives = "Enter Nexus-Point Xenas and stop Lothraxion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86522] = { id = 86522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daylight is Breaking", completion = "This was an impossible mission. We won't forget the sacrifices that bought us a fighting chance.\n\nStill, I know not every victory feels worthy of celebration. When war forces us to choose between friendship and duty, there are many who would be unable to act.\n\nWe will not squander the opportunity you've given us. Now, our counter offensive begins.", objectives = "Report to Lor'themar Theron in the Sanctum of Light in Silvermoon City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86528] = { id = 86528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Cracked Holokey", description = "<A unique-looking ethereal device rests upon the cold ground. It bears a crack down the middle from damage in a scuffle.\n\nPerhaps Alleria will know what it is.>", completion = "I've seen one of these before. Ethereals use them to encrypt communications.\n\nExcellent find, {name}.", objectives = "Bring the Cracked Holokey to Alleria deeper in the Ethereum Refinery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86530] = { id = 86530, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "First, The Shells", description = "Ages ago, on a dismal world of swamp, I led the Army of the Light to a demon-infested manaforge obscured by vines and fog. My soldiers left that world in a haze of flame and smoke, the scent of burning mana and victory in the air. We will do now as we did then.\n\nWe'll begin by collecting the empty canisters they use to hold and transport fuel. The ethereals, and especially their automatons, will have them.", progress = "Just as before.", completion = "Good. The same make I remember.\n\nNow, the catalyst.", objectives = "Collect 5 Empty Manacells from mechs and ethereals at the Ethereum Refinery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86531] = { id = 86531, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Disruption", description = "The Shadowguard may once have defied Xal'atath, but they're part of her army now. Whatever they're doing with the energies gathered here must be stopped.\n\nPut down their soldiers, harvesters, and machines. I'll do the same, and meet you deeper within.", completion = "They will try to rebuild, but we won't give them the chance.", objectives = "Slay Shadowguard and disrupt the Manaforge at the Ethereum Refinery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86535] = { id = 86535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test Run", description = "Hey, you lookin' to make a few coins?\n\nWe made a deal with the earthen to build a teleporter up in Dornogal. We get all the tourism traffic we want, and they get their pick of the finest cracked, chipped, or otherwise unsellable gemstones Undermine's jewelers can offer.\n\nI just got this end of things workin', but I haven't tested it out yet. You wanna try? If you come out the other side, my coworker Kenzi will compensate ya.\n\nWe'll say this constitutes a verbal waiver, yeah?", progress = "Look at this teleporter. Ain't she gorgeous?", completion = "Woah! I thought Rustol was gonna send through a gerbil or a can of peaches or somethin' to test out the new teleporter, not an actual person.\n\nBut you're only sizzlin' a little bit! Fantastic.\n\nTell ya what. For doin' us a solid and havin' such little regard for your own personal safety, we'll let ya use the teleporters free of charge whenever ya want.", objectives = "Use the teleporter to travel from Undermine to Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86536] = { id = 86536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reliable Enemies", description = "The ren'dorei scouts report a familiar enemy upon this world: ethereals. Wretched scavengers and bandits that plague every corner of the Great Dark Beyond. The Shadowguard are the worst of them. We'll handle them.\n\nThis... thing we've taken prisoner must know what they're doing here, and much else. Press the Void's secrets from it. See that it is convinced to share what it knows, or I will employ my own methods.", progress = "Lothraxion has a plan. I trust him.", completion = "If Xal'atath was mortal, then she is all the more monstrous for all that she has done. For becoming what she is now.\n\nOur long battle comes to an end on this world. I swear it.", objectives = "Interrogate Decimus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86537] = { id = 86537, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Network Insecurity", description = "Judging by the design and the strength of this holokey's energy, it must be used to encrypt important communications.\n\nLet us try this lead. See if it's compatible with any of the consoles you find around the refinery. Given the damage it's taken, we'll have to piece together whatever scraps of information we can.", progress = "What have you found?", completion = "Xal'atath.\n\nLet us see this final message.", objectives = "Use the Holokey on consoles around the Ethereum Refinery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86538] = { id = 86538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Second, The Fuel", description = "Ethereals seek corners of the cosmos to drain of potent nether. Arcane, Void, fel--to them, it matters only the yield. And we have a rich vein to work with.\n\nNow, slay those who possess that energy: wild arcane elementals from their pipes, or their ethereal harvesters flush with energy. We have need of it.", progress = "Go. Collect the catalyst.", completion = "Potent. I can feel the energy--radiant. Glorious.", objectives = "Collect 50 Arcane Remnants in the Ethereum Refinery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86539] = { id = 86539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Naaru!", description = "I refuse to let another naaru fall to darkness.\n\nBefore our departure, the scouts reported they had found a Nexus-Point connected to this forge. If the Void's forces possess a naaru, it might be where they're keeping it.\n\nI will prepare the manacells as we conduct the search. Come.", completion = "A naaru, imprisoned. The Light shall give these monsters no mercy.", objectives = "Find Lothraxion at the overlook to Nexus-Point Mid'Ar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86540] = { id = 86540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Third, Blow It Up", description = "The manacells have been prepared. Set them near the pylon and its supporting machinery. When it's done, I will command Alleria to ignite them from afar.\n\nBut we cannot proceed until the naaru has been brought to safety. Go now and I will make certain of her freedom.", progress = "What are you doing here? Place the manacells, now!", completion = "This is taking too long! Every wasted moment brings us closer to ruin!", objectives = "Place 5 Overcharged Manacells at Nexus-Point Mid'Ar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86541] = { id = 86541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just In Case...", description = "Perhaps Lothraxion will be able to bring that shield down on his own. Or perhaps he is a pompous blowhard.\n\nThe Devouring Host offers its trusted soldiers fragments of a relic that can override any ethereal device, including that shield. You'll need to carve quite a swath through their forces to recover enough shards.\n\nBut what do I know? I am merely unworthy voidspawn.", progress = "<Decimus glances sideways at you.>", completion = "A mortal, receptive to outside ideas. Truly exemplary. No need to thank me.\n\nThough, perhaps you'd want to free me of this bondage? I'm feeling a bit chafed by the Light about now.\n\nNo? Oh well.", objectives = "Collect 8 Fragmented Keystones from Devouring Host soldiers at Nexus-Point Mid'Ar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86542] = { id = 86542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flicker in the Dark", description = "We're dawdling! There's no time to waste!\n\nGet that shield down, now! T'era's anguish tears at my soul!", completion = "Everything I could muster. It was simply... devoured.", objectives = "Free and rescue T'era.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86543] = { id = 86543, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magisters' Terrace: Homecoming", description = "We know there's land inside the Voidstorm, through its massive portal. If we can reach it, we can take the fight to Xal'atath.\n\nI have found the key. It is a relic known as the Cynosure of Twilight. For ages, it has mystified us by revealing unreachable pathways to infinite unknowns. \n\nMy research tells me I can use it to open a path to the storm. \n\nThere's just one problem: it's in Magisters' Terrace. And I'm not exactly... in their good graces, at the moment.", completion = "That could have gone better. \n\nThen again, Rommath hasn't killed me, yet. It could have gone worse.", objectives = "Meet Magister Umbric on the Isle of Quel'Danas, then complete the Magisters' Terrace dungeon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86544] = { id = 86544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Post-Mortem", description = "We all bear a heavy burden in this place. I feel myself slipping towards hopelessness. But we haven't failed until we refuse to stand back up. I know my mother will collect herself. But the others need to know this fight isn't over. \n\nSpeak with Hieron. He and the other scouts should have information. We can start there.", progress = "Mother... Hang in there.", completion = "What was that...?", objectives = "Check in with the inhabitants of Locus Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86545] = { id = 86545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Light's Brand", description = "No! {name}, we have to stop them! Lothraxion's boiling temper risks everything! That he chooses now of all times, when my mother is out of commission...\n\nThere's no time. We have to go!", progress = "I should have realized earlier... Join me, {name}. Let us reveal the truth.", completion = "Decimus is a far more capable domanaar than they've been letting on.", objectives = "Intervene in the fight between Lothraxion and Decimus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86549] = { id = 86549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Fear of the Dark", description = "Against all odds, we made it. \n\nI can open a way into the storm, but it will be a tenuous connection. We can only get a small team through the portal. \n\nWe have no idea what awaits us on the other side. We must be prepared. \n\nI can use the Cynosure to bind us to Magisters' Terrace. If we need a quick escape, I can bring us back there. \n\nCome--help me calibrate this spell.", completion = "This... this power! I have never felt the Void like this. \n\nAll-consuming.", objectives = "Help Magister Umbric apply the anchor spell and open a portal to Voidstorm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86555] = { id = 86555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Undermine Benefactor", objectives = "Thanks for helping get Undermine back on track. Here's somethin' for your trouble.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86556] = { id = 86556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shattered Journey Through Time", description = "The Destroyer's star shines upon the land with its piercing light as even the spirits retreat to the shadows. This star is unlike any other in the skies, laying bare the weaknesses of even the boldest heroes. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", completion = "Ah, {name}, you have returned. An otherworldly air hangs heavy about you.", objectives = "Complete 5 Timewalking dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86557] = { id = 86557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Matter of Strife and Death", description = "Ha! A distant realm, crawling with vicious evil monsters? Just like old times.\n\nAlleria, Turalyon, and I faced a thousand years of war with demons in the far-flung realms. It is as simple a solution now as it was then. \n\nKill or be killed.", progress = "I will not deny, I still thrive in the rush of battle. So long as it is of righteous cause.", completion = "Vile beasts. Did you sense it?\n\nThey all reek of Void.", objectives = "Kill 12 monsters in The Ingress.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86558] = { id = 86558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Save a Piece of Mind", description = "The Void here. It is like nothing else. Surely you can feel it, too? The overwhelming power...\n\nWe must do something to stabilize the area. I'm barely able to keep our escape route from imploding, and the rest of our scouts... I can only hope they can hold it together.\n\nThe ren'dorei know what to do. They will place Shadestar Loci to protect this area, but will need your help activating them.", progress = "Be careful, {class}. Treachery threatens us from all sides.", completion = "The void elves risk corruption, and yet are most suited to understanding the world around us. We need their expertise, but cannot trust them.\n\nIt irks me, but I have already sent for more scouts.", objectives = "Activate 3 Shadestar Loci around The Ingress.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86559] = { id = 86559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Far, Far Frontier", description = "We have secured this location. Some void elves can make this into a proper camp.\n\nThere must be some weakness we can exploit to stop the storm. We must bring my army here to mete out justice to Xal'atath's armies!\n\nJoin me and young Arator. Let us see what we can gather from this place across the horizon.", completion = "The rest of the void elves have been dispersed to set up camps or scout.\n\nI am... conflicted over Alleria's presence. Her skills and experience are unspeakably valuable, and yet...\n\nThe Void in her is so strong... I worry. Keep an eye on her.\n\nThe Void can NEVER be trusted.", objectives = "Survey Voidstorm with Lothraxion and Arator.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86560] = { id = 86560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shrouded Journey Through Time", description = "The shrouded star flickers upon the land with its intermittent light ushering in an eerie mist upon the land. This star and the mists bring deep shadows to the land hiding its secrets and dangers. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", progress = "I foresee that you will follow the shrouded star, and walk the paths it reveals.", completion = "Ah, {name}, you have returned. An misty air hangs heavy about you.", objectives = "Complete 5 Timewalking dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86561] = { id = 86561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Strange, Different World", description = "I don't know the purpose of these towers, only that they are called Nexus-Points and they thrum with Void power. We must get more information. \n\nThe domanaar use some kind of Void-infused metal on the beasts here to add them to armies of the Devouring Host. They call it shadowgrafting.\n\nIt empowers them, but also influences their minds.\n\n<Alleria smiles wryly.> \n\nWhat power doesn't? \n\nI have a plan for it. With you here, I can finally act on it.", progress = "The metal on these creatures... it seems particularly conductive to magical energies. Interesting.", completion = "<Lothraxion scowls.>\n\nDespicable stuff. Alleria has explained her plan to me, but I'm not sure I agree.", objectives = "Collect 12 Shadowgraft Fragments in Nexus-Point Antius.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86562] = { id = 86562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dancing with Death", description = "We may be a small strike team, but we are strong. We have you, after all. \n\nThere is no need to move with complete stealth. We must cut a path to the domanaar here. \n\nTake down the strongest enemies you can find. We will join you in the fray.", completion = "There seems to be creatures here both bestial and magical. \n\nThe Void is drawn to violence. I have seen countless worlds drown in it. \n\nCould the savagery of the beasts here have brought the Void in naturally?", objectives = "Slay Voidgrasper, Vathan the Rebel, and Scytheryp the Slicer in Nexus-Point Antius.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86563] = { id = 86563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Savage Journey Through Time", description = "The brutal star shines upon the land, threatening to trample underfoot all who stand in its path. This star is many things: primal, fierce, and noble. While its influence holds, new paths may open up to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", progress = "I foresee that you will follow the brutal star and walk the paths it reveals.", completion = "Ah, {name}, you have returned. An otherworldly air hangs heavy about you.", objectives = "Complete 5 Timewalking dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86564] = { id = 86564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fel Journey Through Time", description = "A corrupting star shines upon the land, threatening all with burning oblivion. The star betrays those who seek the light, its red glow obscuring rather than revealing.\n\nWhile its influence holds, new paths may open up to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", progress = "I foresee that you will follow the corrupting red star and walk the paths it reveals.", completion = "Ah, {name}, you have returned. An fel air hangs heavy about you.", objectives = "Complete 5 Timewalking dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86565] = { id = 86565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Prayer for the Wicked", description = "Alleria has a plan to use this shadowgrafting material to capture that domanaar for information. \n\nBut what good is information given by evil? I've fought countless demons and every one of them was a liar.\n\n<Lothraxion scowls.> \n\nLet us follow her plan, for now. Do what she asks with this metal, then slay the domanaar's pet beast. \n\nOnce we speak with this vile creature, I will decide how long it lives.", completion = "You've done good work, {name}.", objectives = "Help modify the Shadowgraft Fragments, slay Sinewshredder in Nexus-Point Antius, and capture the leading domanaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86575] = { id = 86575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rocket Roll", description = "That scrap was just what I needed. An' now without those bloodfeasters givin' me the heebie jeebies, I can get these bots officially rolled out.\n\nWhile I finish up here, why don't you go tell Benny the good news?\n\nI'm sure he'll wanna deploy 'em right away!", completion = "You helped Trixxie get those bots up an' runnin'?\n\nOutta sight, {name}!\n\nI don't gotta worry about staffing no more.", objectives = "Return to Benny Gooserocket outside the cave in the Ringing Deeps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86584] = { id = 86584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overwhelm Them with Mandatory Time Off" }
quests[86587] = { id = 86587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Maldraxxus", description = "Rays once soared through the skies of K'aresh. While their void-touched descendants are in the skies outside the Oasis, we have no surviving specimens that have not been void-touched.\n\nHowever, I know of a location where we can procure a similar creature that should inhabit the same part of the ecosystem: Maldraxxus in the Shadowlands. Take my portal, and find the creatures for me.", progress = "Greetings.", completion = "Ve'nari sent you? How marvelous! I was just looking for some assistance.", objectives = "Travel to Maldraxxus in the Shadowlands to get some rays for Ve'nari.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86588] = { id = 86588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritualistic Murder", description = "The local ritualists are causing problems for the necrorays. Specifically, plague problems.\n\nIf you kill them, it should lessen the issues for the necrorays.", completion = "What a good apprentice you are.\n\nVery good at following instructions!", objectives = "Slay 13 Morbid Ritualists.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86589] = { id = 86589, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Plague a Day Keeps the Doctor Away", description = "The ritualists have been testing a new plague out on our poor necrorays. This is abominable... That's my job!\n\nBring me some samples of deceased rays and I should be able to concoct a cure for the ones that haven't perished.", progress = "Do you have those samples for me?", completion = "Bah! There is no mastery in this. I've seen oozes spew out better plagues than this! Of course, I made those oozes.", objectives = "Collect 6 Plague Samples from dead Pestilential Necrorays.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86590] = { id = 86590, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Don't Even Work Here", description = "It's good you are here, apprentice! I came to gather the essences from the local rancor. They are wonderful for adding just that little extra spice to a plague.\n\nBut now that you are here, I can have you gather them instead! What an excellent learning opportunity for you!", progress = "Well? Have you gathered the essences?", completion = "What an excellent apprentice you are!", objectives = "Gather 15 Rancor Essences.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86591] = { id = 86591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Poor Imitation", description = "This is Vorax's work. He was once my apprentice, just like you!\n\nHe's trying to replicate my work? Flattering, but sloppy. I'll work on a solution for you, apprentice, while you work on a solution for him.", progress = "Is the deed done?", completion = "Oh bother. I should have asked you to get his remains. I could have used them.", objectives = "Slay Grand Ritualist Vorax.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86592] = { id = 86592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get Your Jabs", description = "If these rays are to travel, we should inoculate them first.\n\nWhat a good opportunity for you to learn about administering anti-plague, apprentice! It's not something that happens here very often.", progress = "Have you jabbed the necrorays?", completion = "I'm glad you were here, apprentice. I find wiping out all the plague in a creature quite unnerving. Feels very unhealthy.", objectives = "Inoculate 5 Calmed Necrorays.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86593] = { id = 86593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Oasis", description = "I suppose you will be heading back now?\n\nIt has been a true joy to work with you, apprentice. I hope we will see each other soon. I'll have some new experiments for you to help me out with. Please do take care of the necrorays! I hope they enjoy their new home.", progress = "Well?", completion = "Well done. I have transferred the necrorays to the Atrium as per our quarantine procedures.", objectives = "Travel to the Oasis on K'aresh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86594] = { id = 86594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Cultured Palette", description = "We're trying to figure out what these rays eat. \n\nI've gathered some options. Can ye put them out? I'll watch for responses.", progress = "Feeding time. Get to it!", completion = "Seems like they'll eat just about anything. Omnivores--that's a handy thing to have.", objectives = "Place 3 Food Items.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86595] = { id = 86595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Custodial Duties", description = "Seems like these rays slough off some gunk as they move. It's congealin' and makin' a mess!\n\nVe'nari sent over this vacuum device to help out. Can you clean things up while yer out and about?", completion = "That ooze is tough. Thanks for takin' care of it!", objectives = "Clean 18 Congealed Lumps in the Atrium.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86601] = { id = 86601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Triple Twenty", description = "Tag the necrorays with these darts. It'll monitor their location and health. It also injects a pain killer so the necrorays don't even notice it.\n\nThese brokers have some incredible inventions!", completion = "Good work tagging those necrorays. We'll be able tae keep a better eye on them this way.", objectives = "Tag 5 Curious Necrorays.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86602] = { id = 86602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Medical Checkup", description = "You said your friend de-plagued those necrorays, but we need to see if the other animals are picking up anything else from them.\n\nCan ye go and collect some samples so we can check for issues?", progress = "Did ye get them all?", completion = "Hmm, these do look healthy.\n\nThat's a bit unexpected, but good!", objectives = "Collect samples from animals in Eco-Dome: Primus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86603] = { id = 86603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ray-ket Ball", description = "It seems one of the necrorays you brought back was pregnant, so I have been dealing with a newborn all day. Thank you. \n\nPerhaps you would not mind testing out its reflexes for me?", progress = "Have you finished playin--er, testing the pup's reflexes yet?", completion = "That data will do quite nicely, thank you.", objectives = "Catch a ball 10 times while playing with your Necroray Pup.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86604] = { id = 86604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dubious Intent", description = "The ooze that Hemet had you collect may be of use to us. \n\nGo and collect the ooze directly from the necrorays. You can use this tranquilizer dart to bring them within range for collection.", progress = "Have you gathered the ooze?", completion = "This should do quite nicely for several different projects around the Oasis. You have our thanks.", objectives = "Collect 7 Necroray Gunk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86605] = { id = 86605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Booster Shots", description = "After some analysis of the samples you brought back, it appears the necrorays are suffering from a vitamin deficiency. \n\nVe'nari contacted Marileth, who prepared something... and then re-prepared it after she requested he remove the plague from it.\n\nPlease gather the necrorays so we can test the initial batches.", progress = "Have you gathered the necrorays?", completion = "Excellent work! We will administer the concoction and monitor for issues.", objectives = "Lasso 6 Tranquil Necrorays and bring them to the Hitching Post by Om'talad.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86606] = { id = 86606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Golden Ooze", description = "Our custodians have yet to do their daily cleanup of the necrorays' discharge. I have many buyers in Tazavesh lined up for this material. They need it urgently, so its collection falls to you.\n\nTake the vacuum device. Compensation will be provided.", progress = "Have you succeeded at your task?", completion = "The Oasis will benefit greatly from your efforts. My thanks.", objectives = "Clean 25 Congealed Lumps in the Oasis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86607] = { id = 86607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Freedom of Ray-cing", description = "Those necrorays responded really well to those treatments you gave 'em! So well in fact that one of 'em is needin' to burn off some energy.\n\nWould ye be able to wear it out?", progress = "Have ye worn the thing out yet?", completion = "That was fast, {name}! Faster than I go, these days. I'll leave the speedin' along to you.", objectives = "Challenge the Zooming Necroray to a race and reach the finish line.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86609] = { id = 86609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Void Breach" }
quests[86610] = { id = 86610, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nor Void of Night" }
quests[86618] = { id = 86618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "License Not Required", description = "Alright. Before you go out and run somebody over let's make sure you know how to do it properly.\n\nWe'll introduce you to the car, the D.R.I.V.E. service we offer, and how to drive it in style.", progress = "Just put your foot on the pedal and the rest will come naturally.", completion = "Great job out there! Now these vehicles don't come with insurance so if you get into any trouble you're gonna have to solve it yourself.", objectives = "Learn how to drive the G-99 Breakneck.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86619] = { id = 86619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Theater Troupe" }
quests[86621] = { id = 86621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wayward Magister", description = "Magister Umbric--he's second only to mother in mastering the Void. If anyone can help us with that storm in the sky, he's the one who can make it happen... if he can forgive the others for not listening to him in the first place. \n\nAt least Lor'themar saw reason. There's no way we can take the fight to Xal'atath without Umbric.\n\nThe forces keeping the Voidstorm at bay will only hold out so long. Let's make haste.", progress = "What's that you have there?", completion = "<Umbric looks stricken.>\n\nThat is not the news I was expecting. No!", objectives = "Accompany Arator to meet with Magister Umbric in Tranquillien.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86622] = { id = 86622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chance Meeting", description = "I've heard some odd rumors myself. Strange happenings to the south--but also to the east and west, and the north. Tranquillien is surrounded by enemies, it seems.\n\nSince you are so dead-set on your investigation, would you look into something for me?\n\nThere is an important report I need from one of my scouts. Check in with them, while I check over the rest of town.", progress = "Let's get to the bottom of this.", completion = "Blast--it appears that cult has ears everywhere!", objectives = "Meet with Lord Antenorian's scout near Tranquillien.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86623] = { id = 86623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Appeal to the Void", completion = "I don't understand. What was she doing with all this information?", objectives = "Assist Umbric with testing Void theorems outside of Tranquillien.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86624] = { id = 86624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rational Explanation", description = "Something just doesn't feel right about all of this. Umbric can look into the notebook, but I suspect there's something more going on here. \n\nIt couldn't hurt to ask around Tranquillien and see if anyone's heard anything odd. I'll take the north side of town, and you take the south.\n\nAnd... use your discretion, my friend. We should avoid alarming anyone for now.", progress = "How goes your investigation?", completion = "There's far more to Tranquillien than meets the eye, it seems.", objectives = "Question the townsfolk of Tranquillien and take note of any clues.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86625] = { id = 86625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Clue in the Inn", description = "Call me paranoid, you'd be correct, but I have been chased out of enough towns that I have a system.\n\nI establish a safehouse. Somewhere easily defensible, with enough materials that I can finish any delicate tasks and prepare for departure. That is the situation we find ourselves in-- we will retreat to the top floor of the inn and assess our options from there.\n\nI had shared the location with Caliea, when she was still studying with me... hopefully it serves us better than it did her.", sourceObjective = "Retreat to Umbric's safehouse on the top floor of the inn.", sourceObjectiveStatus = "unverified-source-field" }
quests[86626] = { id = 86626, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ransacked Lab", description = "My notes, my research... I never should have left it alone.\n\nI was just beginning to understand the Voidstorm! Everything I'd learned, torn from my hands by cultists... Were they watching the entire time? Waiting for me to turn my back?\n\nI cannot let this stop me. They can't have destroyed everything. Perhaps there's enough here to salvage.", completion = "The Twilight's Blade--Antenorian, what have you done!", objectives = "Scour Umbric's ransacked lab for any salvageable research.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86632] = { id = 86632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle for Tranquillien", description = "The Twilight's Blade? Attacking in broad daylight now that their cover's blown... we'll prove what a mistake that was.\n\nSlay the traitors and the creatures they've summoned. Destroy their effigies and their supplies. \n\nMake this retreat costly, {name}.", progress = "Let's hope there's enough left here to rebuild.", completion = "I fear this is far from over...", objectives = "Free Tranquillien from the grip of the Twilight's Blade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86633] = { id = 86633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Comprehend the Void", description = "Kasiea's notes may be lost forever, but we must try and improvise. I have one final ritual to try.\n\nIf this doesn't work, then the answers lay in Deatholme, the Twilight's Blade's heart. But first...", progress = "I can't hold this indefinitely--a little speed would be appreciated!", completion = "No! No... I was so close.\n\n<Umbric collects himself--a paradigm of focus.>\n\nDeatholme it is, then. The base of the Twilight's Blade.", objectives = "Meet Umbric at the ritual site in Windrunner Village. There, collect 4 Void Shards and return them to the Void nexus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86634] = { id = 86634, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Past Keeps Watch", description = "I don't trust the quiet here. Let's shore up the defenses. Did you see those slumped-over arcane golems around the village?\n\nThey may not look like much now, but a quick tune up will have them on their feet soon enough. They're good for standing guard, and also for ferreting out any hidden snakes in the weeds.\n\nLet's get to work. The sooner the golems are running, the better I'll feel about this town's safety.", progress = "It's odd being here. This place is... well, I suppose it's technically my namesake.", completion = "The Twilight's Blade were already skulking around the perimeter... We were right to come here quickly.", objectives = "Activate 6 Decrepit Ranger Constructs on the borders of Windrunner Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86635] = { id = 86635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Deatholme", description = "That coward Antenorian has doomed us all. I had hoped it wouldn't come to this, but...\n\nWe need the rest of Kasiea's research--the missing pages that were stolen from her corpse. But the cult has retreated south, to the ruins of Deatholme.\n\nFitting that such traitors would sequester themselves in such a vile place. But we must root them out.", progress = "Watch your back. The ruins of Deatholme are still dangerous.", completion = "I am loath to find myself here again... but it is the only way.", objectives = "Meet with Magister Umbric in the Ruins of Deatholme.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86636] = { id = 86636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Void Walk With Me", description = "I did not expect this place to be so heavily guarded. This is far more complicated than one charismatic leader and a group of wayward pilgrims. Still... if we take out Antenorian, it should weaken them considerably. A cult is nothing without its leader.\n\nValeera tracked the governor to that cavern. He's gone in. We'll make sure he never comes out.", progress = "Let's be done with this. The Twilight's Blade must fall.", completion = "Kasiea's notes! At long last! I must go!", objectives = "Complete the Deatholme Delve.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86637] = { id = 86637, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anything but Reprieve", description = "This is dire. The Twilight's Blade is much larger--much more powerful--than any of us could have guessed.\n\nI'm relieved Umbric is on the case, but we need to let Silvermoon know what's happened here.", completion = "I was not expecting reinforcements so soon! Is your business with Magister Umbric complete, then?\n\nLet's get moving.", objectives = "Contact Silvermoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86638] = { id = 86638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Choking Tendrils", description = "I haven't the expertise of Orweyna in these matters. But if the Lightbloom moved this quickly, I assume the rutaani are accelerating the spread here just as they were in Fairbreeze.\n\nThe town is beyond saving, but we can at least try to contain the Lightbloom within its walls.", progress = "Fairbreeze was nothing compared to this. What... happened here?", completion = "We've cut back what we can. I only hope it's enough.", objectives = "Cull the Lightbloom in Suncrown Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86639] = { id = 86639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's Left", description = "You see what we have to contend with here. Runestone Shan'dor is helping stop the spread further north, but if this Lightbloom surges again, I don't know if we can halt it.\n\nI've heard cries for help from survivors still trapped within. We have to find them, and direct them to safety!", progress = "By the Light... this is so much worse than I would have ever imagined.", completion = "Some live... I am grateful, as are they.", objectives = "Find and aid survivors in Suncrown Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86640] = { id = 86640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Premonition", description = "I came as quickly as I could. This is... devastating.\n\nI have called in our Magisters to reinforce this runestone. They will keep an eye on the Lightbloom spread.\n\nI suspect Halduron Brightwing and the Farstriders have uncovered more than the villagers know. I can rely on him for anything. We shall rendezvous with him at the encampment to the north, and soon have some answers.", completion = "<Lor'themar falls still, eyes on the shore ahead.>", objectives = "Regroup with Lor'themar Theron at Scintilas Outpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86642] = { id = 86642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Foe Unseen", completion = "What have you found?", objectives = "Find information about what the trolls are doing in Tor'Watha.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86643] = { id = 86643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Following the Root", description = "Lor'themar has a right to defend this land, but I don't think he's seeing clearly. The presence of Amani is too inciting.\n\nThis doesn't add up. The trolls are going out of their way to craft Lightbloom weapons--to fight what? It isn't us. They didn't attack Suncrown. They could have, and they didn't.\n\nWe need to find the truth. Let's head south. That hideout I discovered must have some answers.", progress = "There must be a reasonable answer for all of this.", completion = "The Twilight's Blade are terrorizing Zul'Aman as well? This is no coincidence!", objectives = "Meet Arator at Watha'nan Crypts in Eversong.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86644] = { id = 86644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gods Before Us", description = "I suppose I shouldn't have expected a greeting with open arms, but I did not expect to be trapped in here.\n\nThe Amani are clever. They must have made a way to escape. We have only to find it. Let's look around.", progress = "There's a way out of here--I know it.", completion = "You made that look easy.", objectives = "Explore Watha'nan Crypts and pursue Zul'jan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86646] = { id = 86646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Impasse", description = "How deep does this crypt go?\n\nWe need to find Zul'jan and explain to him that we fight a common enemy. Surely he'll see reason!\n\nCome on. They can't have gotten much farther in this maze.", completion = "This is senseless. We have to stop it!", objectives = "Pursue Vanatha and Zul'jan deeper into Watha'nan Crypts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86647] = { id = 86647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beat of Blood", description = "None of this is necessary. We need to make them see reason!\n\nMy father will know what to do. I know he'll see reason, once I explain what has happened here. There is no need for bloodshed! It's simple: if the Amani are set against the Twilight's Blade, we fight on the same side.", completion = "I must put a stop to this.", objectives = "Meet Arator at the Amani Pass.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86648] = { id = 86648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Light Guide Us", description = "Our findings at Tor'Watha were correct. By the time Turalyon and I arrived here with troops, the Amani had already begun to take the pass. They seek to establish another path to acquire the lightwood from our land.\n\nThe Amani have chosen war, as they always do. This, at least, is a threat I know how to handle.\n\nArator is but a boy. He cannot grasp the magnitude of history between the sin'dorei and Amani--and I don't expect him to.\n\nWill you stand by the blood elves, and all that is right?", completion = "There he is--the one who leads this little incursion.", objectives = "Resolve the battle at the Amani Pass by helping the blood elves secure it, or try to dissuade the blood elves from fighting.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86649] = { id = 86649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Past Redemption", description = "These monsters deserve nothing more than swift retribution. For Silvermoon. For the sin'dorei.\n\n<Turalyon's eyes blaze with Light.>\n\nFor Alleria. This will be finished!", completion = "I did not expect... this. \n\n<Lor'themar glances at Turalyon.>\n\nPerhaps we overstepped our bounds.", objectives = "Finish the battle against the Amani at the Amani Pass.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86650] = { id = 86650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fractured", description = "Lady Liadrin will remain here. The rest of us shall return to Silvermoon and debrief.\n\n<Lor'themar looks at the devastated Turalyon.>\n\nWe still have many battles ahead, it seems.", progress = "There is much to do.", completion = "Would that I could join you, but there is much still to do here in Silvermoon. \n\nYou have your objectives. Keep in touch.\n\nAs for Arator... I hope you find him soon. Anu belore dela'na, {name}.", objectives = "Return to Silvermoon City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86652] = { id = 86652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Left in the Shadows", description = "De loa have not spoken to us in many years... not since I was a young child.\n\nAnd dey have shown no sign of wanting to help us now.\n\nNo. It is up to us alone. We must find a way to rally de other tribes and fight de Twilight's Blade as one.\n\nI will speak to de tribal representatives and help de refugees where I can--dey are our priority.\n\nCome, you might learn somethin' about de Amani.", progress = "Ancestors willing, we will find our opportunity to strike back soon.", completion = "Hash'ey? Has uncle lost his sense?\n\nIt is a tale for children. Maybe if this were de old days, generations ago, before de elves arrived...\n\nBut if de last chance we got is to try to speak to the loa, then I will try.", objectives = "Join Zul'jarra and Liadrin as they check on Atal'Aman refugees.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86653] = { id = 86653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path of the Amani", description = "Kinduru is my uncle, and I trust him... But dis \"path of de hash'ey\"...\n\nThings are not what dey were decades ago. The loa are gone--they not gonna hear us.\n\n<Zul'jarra lets out a low growl only you and Liadrin hear.>\n\nNo. We're running out of options. If dis is de time for old myths and dreams, so be it.\n\nWe meet at the foot of the mountains, Akil'zon's Reach, where de old hash'ey shrines are.", completion = "Dis path is thick with gnarldin.\n\n<Zul'jarra smiles broadly.>\n\nI hope dey try to stop us. I can sharpen my blade on dey bones.", objectives = "Meet Zul'jarra outside Akil'zon's Reach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86654] = { id = 86654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnarldin Bashing", description = "Zul'jarra regards the gnarldin as a fierce, nomadic people that normally keep to themselves. It is clear by their clothing and weapons that they have a primitive but unique culture.\n\nIf the circumstances were different, I would advocate for diplomacy.\n\nBut they are between us and our mission.\n\nThey cannot block our path or continue to damage the shrines or the nests of the eagles that roost here. We will eliminate only those that are in our way. The Amani can choose what to do with them later.", progress = "The gnarldin seem ready to fight us. Let's give them what they want, shall we?", completion = "Good. Hopefully that clears the path to the shrines and the temple enough for our purposes.", objectives = "Slay 12 gnarldin in Akil'zon's Reach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86655] = { id = 86655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "De Ancient Path", description = "My uncle, de loa speaker, spoke of de hash'ey when I was a child. But when de loa remained silent so many years...\n\nI do not think he would admit it, but he lost a little faith too.\n\nI remember some of his lessons.\n\nA chieftain must light de shrines on de way to de temple. De hash'ura must as well. Why? I do not remember.\n\nBut if it is de only way to get de loa's favor? Come. Let us get dis out of de way.", progress = "I hope we are doing dis right.", completion = "De shrines are lit.\n\nNow what do we do?", objectives = "Light the 4 Hash'ey Shrines in Akil'zon's Reach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86656] = { id = 86656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brutal Feast", description = "<Zul'jarra's brow furrows and her lip curls as she looks toward the temple.>\n\nWhen we lit de last shrine, some of de eagles returned to de temple. It could be a sign.\n\n<Zul'jarra scoffs.>\n\nOr de eagles are movin' in after de gnarldin started movin' out.\n\nWhen we get to the temple, all we gonna find is silence. Just like always.\n\nBut we still gonna try. We should go now and present an offerin'.", completion = "That voice...\n\nYou heard it too, {name}?", objectives = "Reach the Temple of Akil'zon and seek Akil'zon's attention.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86657] = { id = 86657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadebasin Watch", description = "<Zul'jarra smiles slightly as Akil'zon's blessing buffets her.>\n\nKinduru's stories were real. We have de blessin' of Akil'zon, and de path of the hash'ey stretches out before us.\n\nWe must follow Akil'zon's advice and seek out Halazzi next. As Akil'zon is de loa of de rulin' tribe--de Amani--and my family, Halazzi is de loa of the Witherbark and their leaders.\n\nIf their loa speakers are gone, then maybe Kul'amara will know how to approach him.", progress = "I thought de Witherbark were strong enough to handle de Vilebranch on their own. I should have come here before now.", completion = "De Vilebranch have caused my people sufferin' for too long.\n\n<Zul'jarra glares in fury at the nearby Vilebranch village of Maisara.>\n\nIt's been a long time coming, but now's de time to deal with them.", objectives = "Speak with Kul'amara the Fierce at Shadebasin Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86658] = { id = 86658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crypt in the Mist", description = "<Zul'jarra growls through her gritted tusks.>\n\nNow it's not as surprisin' dat Malacrass's tribe, de Vilebranch, fell to the lure of hex magic.\n\nBut dat is their choice and a path dey chose long ago--a path away from us.\n\nI won't let dem live long enough to regret it.\n\nWhat de Vilebranch have done to de Witherbark has gone too long without an Amani response. De mist is not in our way.\n\nWe can use it to our advantage.\n\nWe will take a life for all de lives dey took. And make sure dey stay dead.", progress = "Finding Halazzi can wait. The Vilebranch are preyin' on my people. It's about time some predators hunted dem.", completion = "<Zul'jarra spits on the ground.>\n\nDisgusting. Dey deserve to be brought back and killed a hundred times.\n\nI hope whatever loa awaits dem in de afterlife swallows dem whole and grinds dem with its back teeth.", objectives = "Slay 8 Vilebranch trolls and Ritualist Zongha in Numazon Crypt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86659] = { id = 86659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaching the Mist", description = "The Vilebranch seemed to be just as confused by the mist as the Witherbark.\n\nWhatever has caused de mist, dealin' with de Vilebranch changed nothing.\n\nAnd now we must find de hash'ey shrines in de dark.\n\n<Zul'jarra moves her hand in front of her face, testing her range of visibility, and frowns.>\n\nWe must light de shrines. Try not to get separated.\n\nDis will try my patience. But I'm sure if we use our heads, we will find de path.", completion = "Findin' Halazzi and de hash'ey shrines has taught me patience. And forced me to think through my obstacles, instead of cuttin' my way through dem.\n\nI wish Zul'jan were here. He would be proud of me for gainin' some brains. Heh.", objectives = "Light the Hash'ey Shrines around the Temple of Halazzi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86660] = { id = 86660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rescue from the Shadows", description = "Kul'amara has told me dat a shadowy mist has fallen over Numazon. She believes de Vilebranch are behind it, usin' their magic to hide de crimes dey commit against de Witherbark.\n\nShe believes dey are hidin' in de Numazon crypts. De hash'ey shrines are near there as well.\n\nWe must find our way to Numazon and rescue de Witherbark captives. If we find de hash'ey shrines along de way, so be it.\n\nIf Halazzi will not stand with us, den maybe de Witherbark will.", progress = "Keep on de lookout for more Witherbark captives!", completion = "So that's why the Vilebranch wanted de Witherbark--to please de Twilight's Blade by givin' dem more soldiers.\n\nUndead soldiers. Obedient soldiers.\n\nAnd we have already lost too many.", objectives = "Rescue 8 Witherbark captives in Numazon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86661] = { id = 86661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coals of a Dead Loa", description = "By helpin' de Witherbark, we helped ourselves--and passed Halazzi's trial.\n\nThere is a lesson in that.\n\nNow dat Halazzi has returned, we should go back and let Vun'zarah know. I hope dis will improve de relationship between our tribes.\n\nAnd maybe he knows where we can find out how to resurrect Jan'alai.", progress = "We have come dis far. We must try to resurrect de dead loa.", completion = "\"Eccentric loa speaker.\"\n\nHeh. That sounds familiar. I guess dey are all like dat.", objectives = "Travel to Witherbark Bluffs and speak with Vun'zarah, leader of the Witherbark Tribe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86663] = { id = 86663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Embers to a Flame", description = "The loa speaker talks of fire in de heart--in all hearts.\n\nJan'alai is de loa of birth, death, and rebirth. Maybe de loa speaker is askin' for sacrifice.\n\n<Zul'jarra smiles deviously.>\n\nHey, Liadrin. How much fire you think is in an elf's heart, eh?\n\n<Liadrin gives her a sour look.>\n\nHeh.\n\nWhatever de loa speaker wants, it is either part of resurrectin' de loa or part of de trial. Lets see what he has do say.", progress = "This loa speaker's holding onto his faith a bit like Kinduru. But Kinduru knows how to speak clearly what he means. Usually.", completion = "<Zul'jarra watches the flames dance in the coals. A small smile creeps up on her face. She balls her fists and flexes her arms.>\n\nI think dis trial is starting now.\n\nWhatever it throws at me... I'll be ready!", objectives = "Slay Amazards to empower the Ember of Jan'alai.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86664] = { id = 86664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seer or Sear", description = "Dis old, crazy loa speaker is too busy dancin' to tell us what to do next.\n\nBut I think I know.\n\nWe could not light de shrines on de way to de temple. But now dat Jan'alai's presence is here...\n\nMaybe now we can.\n\nI will take de ember to de hash'ey shrines. Den maybe de trial will start.\n\nI jumped from de top of de temple of Akil'zon. I found my way through de mists of Halazzi.\n\nI am ready for Jan'alai's fire.\n\nWe can only hope dey will receive us after what my grandfather has done.", progress = "No stoppin' de trial now. We must do what needs to be done.", completion = "<Zul'jarra brushes some ash off her shoulder.>\n\nJan'alai's flame... it has taken de doubts from my heart and given dem form.\n\nI... was not prepared for dat.\n\nWhat else do they have in store?", objectives = "Assist Zul'jarra in lighting Hash'ey Shrines of Jan'alai.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86665] = { id = 86665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Face in the Fire", description = "First my grandfather, then my brother.\n\nJan'alai knew my shame at my grandfather's rage. And de rage I feel when Zul'jan disrespects me. I know I put fuel on his fire by respondin' de way I do. \n\nMaybe dat needs to change. I have left my doubt of de loa behind me. I can leave those thoughts behind too, and continue de path of de hash'ey.\n\nStoke de coal, {name}. I am ready for de final trial, whatever it may be.", progress = "Let's get dis over with.", completion = "Fittin' that de last test be facin' my own doubt. About my leadership and my choices.\n\nIt felt good. As if de doubt melted away.\n\nAnd I gotta say... I never seen flames so fit and handsome.\n\n<Zul'jarra, despite it all, laughs heartily and claps you on the shoulder.>", objectives = "Slay the last Fire Manifestation in the Temple of Jan'alai.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86666] = { id = 86666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In the Shadow of Rebirth", description = "Jan'alai's trial has made me realize...\n\nI need to make things right between me and my brother.\n\nHe acts out at me, but it's because I put him down. I do not think about how hard it must be to be my brother.\n\nWe should also check on how our preparations are goin' and if my troops are gettin' de food and rest dey need.\n\nNalorakk's not gonna go anywhere. He can wait a few hours.", completion = "So many dead...", objectives = "Meet Zul'jarra in Amani'Zar Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86681] = { id = 86681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den of Nalorakk: A Taste of Vengeance", description = "Zul'jan has taken de troops without my orders--again!\n\nAnd de number of casualties... for what? For wood?\n\nI want to take his tusks and...\n\n<Zul'jarra growls but seems to center herself.>\n\nKinduru will need help with de soldiers' death rites. Help him prepare de herb mixture and pour it onto de fires.\n\nMy brother and I need to... talk.", progress = "There are so few of us left. What was my brother thinking?", completion = "I love my brother. We are as de day is to de night. But even so, as children we were close.\n\nZul'jan is smart but he doesn't understand. A victory means nothin' if there is no one left to celebrate it.\n\nHe is supposed to be my right hand, not a pain in de neck.\n\nI hope I have not left Zul'jan without guidance too long to turn him around.", objectives = "Assist Elder Kinduru with the death rites.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86682] = { id = 86682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den of Nalorakk: Waking de Bear", description = "We must set aside what Zul'jan has done and focus on de final hash'ey trial: facin' Nalorakk, de Loa of War.\n\nDe Revantusk were once beloved of Nalorakk. Legend has it dat his loa speaker was so devoted, she followed him into his temple and his den with de most faithful of de Revantusk's warriors.\n\nBut now de temple is sealed. We cannot speak to de loa speaker, but maybe Lilaju knows how to get Nalorakk's attention.\n\nShe keeps watch for de Twilight's Blade at Torntusk Overlook with her guards.", progress = "Lilaju is de only person who can help us now.", completion = "I do not pity Lilaju--I was around her age when I took my place as leader of de Amani.\n\nI am proud of her. She is stickin' up for herself and her tribe.\n\nShe gave us what we needed. And I will not go back on my promise of helping her.", objectives = "Travel to Torntusk Overlook and speak with Lilaju, the Revantusk leader.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86683] = { id = 86683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hash'ey Away", description = "We've done it, {name}. De loa are at our side once again.\n\nAm I hash'ey? I do not know. But I do know I would not have gotten dis far without my hash'ura.\n\nCome. We will return to Amani'Zar and tell Kinduru and Zul'jan de good news.", completion = "Now dis will be a fight!", objectives = "Meet Zul'jarra at Amani'Zar Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86684] = { id = 86684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blade's Edge", description = "With de other tribes and de loa's help, we can take de fight to de Twilight's Blade and take dem down.\n\nBlood for blood!", completion = "<Zul'jarra's piercing eyes survey the battlefield. She mutters under her breath what you can only imagine is troll profanities. You hear her say \"Jan\" among them.>\n\nDe battlefield is full of bodies. De bodies of my people. But there are more still in de fight!\n\nThere is time to turn de tide!", objectives = "Meet Zul'jarra and Liadrin at Broken Throne to fight the Twilight's Blade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86685] = { id = 86685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chip and Shatter", description = "<Zul'jarra shakes her head back and forth and jumps in place, shaking out her muscles.\n\nShe stops and turns to you, grinning broadly.>\n\nHeh. Do you feel it, my hash'ura?\n\nDe electricity in de air? De smell of blood and fire?\n\nMy soul is leapin' to join de fight.\n\nYou ready to chop de enemy down, bathe in dey blood, and make dem pay for what dey done?\n\nMe too.", completion = "That was good.\n\nBut I still thirst for more.", objectives = "Slay the Twilight's Blade at Broken Throne.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86686] = { id = 86686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Light Indiscriminate", description = "Though the dead litter this field, I still see plenty of Amani clinging to life.\n\nHelp me heal the injured. We'll ensure their reputation for survival continues on after this day.", progress = "Every warrior healed is another sword at our side!", completion = "I look forward to Lor'themar's expression when I report back.\n\n<A slight smile creeps across Liadrin's blood-spotted jaw.>\n\nIt's bound to be worth more than my inevitable reprimanding.", objectives = "Heal 10 Injured Amani Warriors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86687] = { id = 86687, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conduit Crisis", description = "With de loa at our side, we can finally break de Twilight's Blade and return to Amani'Zar with Mor'duun's head.\n\nDe loa are already attackin' de main source of Mor'duun's power: summoned spheres of pure void energy.\n\nGo to de loa and offer your assistance. When de orbs are destroyed, we can move forward and strike at Mor'duun!", progress = "Don't be afraid. If you assist dem, de loa will grant you their strength.", completion = "The sight of de loa fightin' by their side has filled our warriors with hope.\n\nDey remember dat dey are Amani!", objectives = "Destroy the 12 Void Conduits hindering Nalorakk, Akil'zon, Halazzi, and Jan'alai in Broken Throne.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86692] = { id = 86692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blade Shattered", description = "It ends here. De path of the hash'ey, my path, has led me here.\n\nLet dis fight bring a new age for my people.\n\nCome. It is time.", completion = "<Zul'jarra snorts and spits out a viscous wad of blood, broken tooth included.>\n\nIt is done.", objectives = "Slay Mor'duun, High Inquisitor of the Twilight's Blade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86693] = { id = 86693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "De Legend of de Hash'ey", description = "Mor'duun is slain.\n\nDe Twilight's Blade will continue to plague our lands, but of dem only Mor'duun's \"fodder\" is left. Dey will be easy prey for us.\n\nAnd now I will say somethin' my uncle would be proud of. Let us follow de teachin' of Nalorakk, de Loa of War.\n\nDe battle is over. It is time to rest--I can tell by your eyes both my hash'ura need it too.\n\nLet us leave dis place. We can speak again back in Amani'Zar.", completion = "It did not occur to me dat what we would be celebratin' would be... me.\n\nThere has been no hash'ey among de Amani since before de elf and human war thousands of years ago.\n\nIt is a great honor, but one I am not sure I have yet earned.\n\nI will strive to live up to it.", objectives = "Speak with Zul'jarra in Amani'Zar Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86696] = { id = 86696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadow Re-Disruption" }
quests[86697] = { id = 86697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cleanup Crew", description = "Even if we got bots out there an' not workers, there are still gonna be monsters out there gettin' in their hair, er, wirin'.\n\nGet out there an' thin out the wildlife. That'll keep our bots from gettin' damaged and voidin' whatever warranty they got left.\n\nThe longer they can stay out there, the longer we can stay right here!", progress = "Got any good news, kid?", completion = "That's what I'm talkin' about!\n\nNow those bots'll be able to work without bein' hassled by all them nasty Black Blood monsters out there.", objectives = "Kill enemies in the Writhing Fields in the Ringing Deeps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86698] = { id = 86698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work It", description = "The Trial of Style gives us the opportunity to look good. {class}.\n\nThe camera makes sure we keep looking good. \n\nSo focus on me and my camera, follow my directions and I'll make sure you look fantastic!", progress = "Focus on me and follow my directions. \n\nI'll make sure you look great.", completion = "The camera doesn't lie, {name}. \n\nYou are one stylish {class}.", objectives = "Focus on the photographer and follow their directions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
