quests[86706] = { id = 86706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking Knowledge of the Past", description = "Greetings, {race}. I must seek your aid. Soridormi and our kin have journeyed to Khaz Algar to help in this fight against the Void's new master.\n\nWe think that we can provide insight and valuable information about past attacks by the Void. \n\nSeek her out near the southern edge of the Coreway.", completion = "You are just in time as always! Let us speak of what brings me here.", objectives = "Seek out Soridormi near the Coreway in Dornogol on the Isle of Dorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86707] = { id = 86707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shadowguard Resurgence" }
quests[86708] = { id = 86708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gates of Zul'Aman", description = "After the Amani surrender, we demanded Zul'jan relinquish our lightwood and return to their lands. Even so, Zul'jan still lingers at the gates of Zul'Aman with his troops.\n\nLady Liadrin and her Blood Knights hold the pass, and Liadrin is trying to remedy the situation with diplomacy, but she reports that aggression may begin anew.\n\nShe requests your assistance in this precarious matter.", completion = "Our ceasefire is strained, but holding. For now.", objectives = "Meet Lady Liadrin at the Amani Pass.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86709] = { id = 86709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mana Falling from the Skies" }
quests[86710] = { id = 86710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Line Must be Drawn Here", description = "I had hoped that Zul'jan would leave the lightwood and return swiftly to his lands after our confrontation with him.\n\nBut dealing with the Amani has never been a simple matter.\n\nDiplomacy is the only way to avoid more bloodshed, but Zul'jan is finished listening to me.\n\nPerhaps he will listen to you?", progress = "An outsider's view may help him see reason.", completion = "I find myself relieved to discover Zul'jan is not the leader of the Amani.\n\nBut this \"Zul'jarra\" might be worse.\n\nNo matter. We must get on the other side of that gate and assess the Twilight's Blade's threat to Eversong.", objectives = "Speak to Zul'jan and diffuse the situation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86711] = { id = 86711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amani Clarion Call", description = "If you want to survive here in Atal'Aman, find and beat de city's battle drums. Dat will rally our remainin' soldiers forward to join de fight.\n\nIt will also bring all de tribes of Zul'Aman--de Witherbark, de Revantusk, and de Shadowpine--to our aid and tell our civilians to retreat to de Altar of Malacrass if we need to evacuate.\n\nUse the drums to spread de word. Find me at de Altar of Malacrass when you are done.", completion = "Many Amani found their way here, but we have more to aid.\n\nAnd even more enemies to kill.", objectives = "Sound the Amani War Drums in Atal'Aman.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86712] = { id = 86712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Amani Stand Strong", description = "Zul'jarra doesn't think de lightwood is worth de risks I am taking. We will prove her wrong.\n\nI have seen too many warriors discouraged because their weapons don't work against de Twilight's Blade.\n\nDon't just tell them to retreat. Give them de lightwood weapons.\n\nNothing stirs Amani blood like an effective axe in their hands. Let dem fight their way back to de Altar of Malacrass.", completion = "De troops we armed have killed a great many Twilight's Blade.\n\nSome survived and made their way here.\n\nWe lost a few, but I think de sacrifice was worth it.", objectives = "Give 8 Lightwood Weapons to Demoralized Defenders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86715] = { id = 86715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rituals Cut Short", description = "In our reconnaissance flight around the city, Zul'jarra and I got a look at the Twilight's offensive. They're summoning more Twilight's Blade directly into Atal'Aman.\n\nWe can counter them by disrupting their dark summoning rituals. That will stop the flow of their cultists into the city and give the Amani time to strategize.\n\nKill the ritualists, and any trollbreakers already portaled into the area.", progress = "We cannot allow the Twilight's Blade to bring even more troops into Atal'Aman.", completion = "That should slow them down--at least for the moment.", objectives = "Destroy 6 Twilight Ritualists and 6 Twilight Trollbreakers in Firewing Terrace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86716] = { id = 86716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armed by Light", description = "You might be good at killing, {class}, but so are we Amani.\n\nAnd even more de better our weapons!\n\nI took an army into Eversong to reclaim de lightwood forests for de Amani. It was against my sister's orders, yes, but lightwood gives us an advantage.\n\nTake back de weapons being stolen by the de Twilight's Blade, and I'll show you why it was worth de effort.", progress = "These weapons are the difference between my people living or dying.", completion = "Good.\n\nNow we have teeth to bite back with.", objectives = "Recover 8 stolen Lightwood Weapons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86717] = { id = 86717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Show Us Your Worth", description = "De Twilight's Blade's General, Mor'duun, has got us by de throat. We're not winnin', and we are too few.\n\nWe've got to evacuate before there's no one left--and hope de other tribes meet us at Amani'Zar.\n\nIn de meantime, I'm glad to use you while we rally de people of Zul'Aman. \n\nDe civilians' lives are my priority. Go to Swiftclaw Terrace and evacuate de people there.\n\nTear through de Twilight's Blade as you go. Find your way to Zul'jan when you're done.", progress = "Separate their limbs from their bodies. Tear down their banners and shelters too!", completion = "You cleared de way, but Mor'duun continues to keep us scrambling and off-balance.\n\nWe're gonna need as many lightwood weapons as we can get to end this.", objectives = "Rescue Amani civilians and destroy the Twilight's Blade presence at Swiftclaw Terrace in Atal'Aman.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86718] = { id = 86718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Bled", description = "Mor'duun may be de leader of de Twilight's Blade in Zul'Aman, but dat ogre can't be everywhere. De elf found his military commander--a hulkin' pile of armor and flesh named Benvis Bladesplatter.\n\nHe's paradin' 'round like he's already won just because dey seized Firewing Terrace.\n\nMake him pay for his arrogance.", progress = "Have you ended him yet?", completion = "The next to fall will be Mor'duun.", objectives = "Kill Benvis Bladesplatter at Firewing Terrace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86719] = { id = 86719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Important Amani", description = "De drums have sounded. But de elders have not come.\n\nWe cannot lose them. They are our link to our culture--our sages and our best minds.\n\nTorundo helped devise de lightwood weapons. And Doru is our provisioner. We will need both if de battle goes on.\n\nGo find Doru in de market and Torundo in de tribute hall.\n\nDe last one is de old loa speaker--our uncle, Kinduru. He may need... special persuasion to leave. I will go to Talonstrike Terrace to speak to him. Meet me there after you find de others.", progress = "Do whatever is necessary to get Kinduru to leave.\n\nHe's our uncle. We can't leave him here.", completion = "Eagles... loa... we don't have time to dwell on de spirits of the past.", objectives = "Find the Amani Elders: Torundo the Grizzled, Doru, and Kinduru.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86720] = { id = 86720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Break the Blade", description = "Zul'jan's ballista is ready. And it had better work after what he has done.\n\nWe lost de army we needed to defend de city, but we can fend off Mor'duun long enough to let our people escape.\n\nHelp my brother man de ballista. Focus on de shadow warders and de pylon. Liadrin and I will distract Mor'duun.\n\nI will kill him if I can, but even then we can't stay here. There's too much void energy. And too much destruction. Atal'Aman is truly lost.", completion = "<Zul'jarra seethes with rage.>\n\nMor'duun is playin' with us. He coulda stayed and destroyed de city outright.\n\nIf chaos is de Twilight's Blade's plan, we need to prepare.", objectives = "Use the Lightwood Ballista to destroy the Empowering Shadows and the Scrying Focus to bring down Mord'uun's barrier.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86721] = { id = 86721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Everything We Worked For", description = "My blood is boiling! While waiting for Kinduru, de Twilight's Blade was destroying what little stores of lightwood we had left at Ragemaw Terrace!\n\nBut if we act quickly, we can save enough to arm de lightwood ballista--and take a shot at Mor'duun.\n\nAnd without de ballista, we cannot claim victory!", progress = "Don't let de lightwood burn!", completion = "We lost so much of it...\n\nWe could have blacked out de sky with ballista bolts!\n\nBut dis still may be enough. It will have to be!", objectives = "Extinguish fires on the Lightwood Piles at Ragemaw Terrace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86722] = { id = 86722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heart of the Amani", description = "You and your elf friend amuse me. And you've more than proved yourself in battle.\n\nOur people are headin' to Amani'Zar. We hope dat de other tribes rallied there instead of Atal'Aman. Their representatives will give us council, and then we will mount an attack on de Twilight's Blade.\n\nIf you still wish to fight with de Amani, meet me on de northwest side of de village. Zul'jan will have gone ahead to speak of his deeds--and yours--but do not enter de village without me. Amani kill strangers on sight.", completion = "Tokobo'ne na Amani'Zar, {name}. Welcome to Amani'Zar.\n\nBecause you are my guests, my people will not harm you... unless I say so.\n\nDon't give me a reason, yeah?", objectives = "Meet Zul'jarra at the entrance to Amani'Zar Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86723] = { id = 86723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Isolation", description = "We will speak to Torundo, my war advisor. And if de representatives of de tribes are here, we will have a council meetin' in de Zari Lodge.\n\nTogether, we must agree on a way to defeat de Twilight's Blade.\n\nExplore de village if you want. But keep your weapons where dey can be seen. You are here by my invitation and my word is law, but I can only run so fast if one of my people thinks you looked at dem in de wrong way.\n\n<Zul'jarra smiles a tusky grin as if proud of her people's short fuse.>", progress = "I need de advise of my advisor, Torundo. And we must see why de other tribes did not heed de drums.\n\nDey may think I am desperate to ask for your help. But dey also would dare not challenge me.", completion = "There is... much you do not know about us and de loa.", objectives = "Meet Zul'jarra and Liadrin to assess the situation with the other troll tribes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86728] = { id = 86728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Floodgate: Disposing of the Garbage", description = "Hey, pal. I've heard murmurs of a real piece of work trying to siphon off energy at the Waterworks in the Ringing Deeps.\n\nStealing from our stone friends ain't good for business, and it certainly ain't something we're willing to let continue.\n\nI know you've made a name for yourself for disposing of the trash, and bad business folks are certainly as trashy as they come.\n\nDo me a favor, will ya? Weapons are optional, but attitude is required... if you catch my drift.", progress = "Yo, you take care of that \"thing\" for me?", completion = "Thanks pal. The cartels will remember what you did for them.", objectives = "Defeat Geezle Gigazap in Operation: Floodgate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86731] = { id = 86731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Original Path Through Time", description = "Ever since your city fell out of the sky, I have learned more of this world's history and the challenges that heroes like yourself have faced. \n\nLearning from the past is how we ensure our future. Walk through time to the humble beginnings, defeat those threats once more, and bring those lessons forward.", completion = "What lessons do you bring from your journeys through time?", objectives = "Complete 5 Timewalking dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86733] = { id = 86733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silvermoon Negotiations", description = "It would be an understatement to say things between Silvermoon and the Alliance are often tense and uneasy. I thank you for setting aside any prejudices you might have had and lending your strength to the defense of Silvermoon and the Sunwell.\n\nWe have Xal'atath's forces held for now, but this is far from over.\n\nI would include you in our next steps. Meet me at the Sanctum of Light.", completion = "I'm glad you've arrived. Let's begin.", objectives = "Journey to Silvermoon City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86734] = { id = 86734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diplomacy", description = "We shall all weigh in on the situation.\n\n<Lor'themar glances at Umbric and Rommath.>\n\nAs you can see, there are many tensions at play.\n\nPlease give us a moment to discuss.", progress = "We have much to discuss.", completion = "There are those that will disagree with my decision. But I will not have us lose our home. If we must host temporary guests, so be it.", objectives = "Listen to the discussion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86735] = { id = 86735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paved in Ash", description = "Now that the matter is settled, you should acquaint yourself with Silvermoon. There are a few key civilians I'd like informed about your presence here--you should check in with them.\n\nShow them my signet ring--they'll know you've my permission to be here. But please take care where you go, and stay in the outer city to avoid any issues.", progress = "Have you spoken to everyone yet?", completion = "Remember, you are a guest here. Your aid is appreciated, but our rules must be followed while you are within these walls.", objectives = "Show Lor'themar's Signet around the city.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86736] = { id = 86736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paved in Ash", description = "I've more to review with Turalyon, but in the meantime, the rest of the city should be informed that we will have some temporary guests in the outer perimeter. I'd like you to check in with a few key civilians and deliver the news.\n\nWhile you're out there, take the chance to familiarize yourself with Silvermoon. We've made impressive strides rebuilding it since you've last visited.", progress = "Have you met with everyone?", completion = "While the Alliance and the Vanguard may become an additional stress for some, their presence is to be tolerated... for now.", objectives = "Check in with civilians around the city.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86737] = { id = 86737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fair Breeze, Light Bloom", description = "In recent years, small pockets of wild growth we call \"Lightbloom\" have blossomed throughout Eversong. A curiosity for our local botanists, for the most part.\n\nHowever, the Magistrix in Fairbreeze is asking for help with the local Lightbloom. Every capable hand I have is focused on holding back the Voidstorm--but if the Magistrix cannot handle the matter herself, it requires swift attention.\n\nI'd like you to see to the issue. Magister Rommath can provide you with an arcane projector to keep in touch.", completion = "Thank goodness--everything is completely out of control!", objectives = "Journey to Fairbreeze Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86738] = { id = 86738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sharpmaw", description = "These beasts roaming the village are nuisances, but we have a bigger problem.\n\nThere's a feral lynx prowling nearby that we call Sharpmaw. She used to keep her distance from the village, but the current situation has made her more bold. We've plenty of little ones around here, and more than once the guards have caught that beast eyeing them like they were a snack waiting to be snatched. \n\nStop her before she starts attacking my people in earnest!", completion = "A what? Giant plants? Yet another problem... at least that beast is gone for good. Thank you.", objectives = "Slay Sharpmaw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86739] = { id = 86739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fairbreeze Favors", description = "This is the oddest situation I've ever been in--our village is being overrun!\n\nI like to keep things neat and tidy around here, but these animals... they've come in from the wilds like they own the town. They're attacking our sweet pets, overturning our belongings, and causing havoc. No sooner have I solved one problem than another is rearing its head. I'm only one elf--I can't stop all of this on my own!\n\nLend a hand, won't you? This... elf... troll... person hasn't lifted a finger.", completion = "Thank you so much. Maybe now I can get this village back to some semblance of order!", objectives = "Help restore order in Fairbreeze Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86740] = { id = 86740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Displaced Denizens", description = "The wildlife here seems to have been upset by something. Perhaps this is why the world's song bade me here: to discover why and correct it.\n\nStudy the displaced wildlife. Bring me your findings. If there is anything unusual, I wish to know of it. I will speak with the Magistrix. Perhaps together we can uncover this mystery.", progress = "Perhaps we can solve this problem together.", completion = "This Lightbloom--it seems to be the cause of every trouble here.", objectives = "Study 3 disturbances caused by displaced wildlife and 3 unusual plants in Fairbreeze Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86741] = { id = 86741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lightbloom Looming", description = "The wildlife seems to have been displaced from the south. It is there we will surely find answers.\n\nCome--I will use my magic to illuminate the path and we will follow the trail.", completion = "These creatures all come from here. This Lightbloom... this is where the song of the world was leading me.", objectives = "Follow the trail of the displaced wildlife.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86742] = { id = 86742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Curious Cultivation", progress = "This makes no sense.", completion = "The rutaani are not like this! Not where I am from, at least. There is something affecting them. This behavior is not normal.", objectives = "Examine 3 Lightbloom Plant Growths in Lightbloom Ath'Ran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86743] = { id = 86743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trimming the Lightbloom", description = "The creatures of this Lightbloom see us as the intruders. They threaten the surrounding wildlife and inhabitants who are naturally here.\n\nWe should reduce their numbers and end this threat.", completion = "This will bring some peace to the region for now, at least.", objectives = "Kill Lightbloom creatures in Lightbloom Ath'ran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86744] = { id = 86744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking Truth", description = "I will channel on this strange seed we have collected, and see if I can discover what has happened here.\n\nThis may upset the rutaani. Make sure I am not interrupted. This is why I was called here--I know now. But I must discover what needs to be done.", progress = "Ah... perhaps we have some answers.", completion = "The rutaani are trying to spread the growth of the Lightbloom as far and wide as possible. But why?", objectives = "Defend Orweyna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86745] = { id = 86745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silvermoon Must Know", description = "This growth--Lor'themar needs to know about this. I worry what will happen should it get out of control. \n\nAnd the Light's influence... my father should know, too.", progress = "We must contact Silvermoon to give them an update.", completion = "I hate to leave this as it stands... but Silvermoon should have enough information now to keep the Lightbloom at bay, while we wait for Orweyna's investigation.\n\nUntil then... we cannot address matters at the Sunwell without Umbric.", objectives = "Contact Silvermoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86769] = { id = 86769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Last Bastion of the Light", description = "Your arrival has reignited hope.\n\nWe have pushed Xal'atath's forces away from the Sunwell, yet they still infest the Isle of Quel'Danas, and appear to be massing for another attack as they prey upon the sin'dorei.\n\nWe must join up with the Vanguard of Light.", completion = "We must use this miraculous event to turn the tide against chaos. We must not falter.", objectives = "Follow Lady Liadrin to Parhelion Plaza.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86770] = { id = 86770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champions of Quel'Danas", description = "Lor'themar has formed a rally point at Sunstrider Rise, while the civilians there are evacuated to Silvermoon, but the forces of the Vanguard of Light are scattered throughout the battlefield.\n\nWe need to fight as one to defeat this host. Together, we can defeat Xal'atath and save the Sunwell.", progress = "You have gathered help?", completion = "Thank you, {name}. With this force, we can protect the survivors and escort them to the boats.", objectives = "Rally Faerin Lothar, Lothraxion, and Alonsus Faol at Light's Spire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86775] = { id = 86775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urge to Surge", description = "Occasionally we get more jobs than we can handle. You know what that means-- big money. Help out during some Surge Pricing and we'll see to it that you're thanked for your help.", progress = "Keep an ear out for when we call for help. Usually it happens within the hour.", completion = "Wow. We were swamped. Thanks for the help!", objectives = "Complete a Surge Pricing event at least once.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86780] = { id = 86780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where Heroes Hold", description = "We have stopped the Devouring Host's initial attack. This battle will not be won if we go on the defensive, not even to safeguard the innocents of Quel'Danas.\n\nFocus on culling the Voidfront. Without their invading force, the Devouring Host cannot maintain a foothold!\n\nWe will rally at Sunstrider Rise when ready.", progress = "Have you thwarted the enemy?", completion = "Excellent work, {name}. Their numbers dwindle as ours grow. The Light truly has brought hope to this battlefield.", objectives = "Hinder the Voidfront forces along the walls of Parhelion Plaza.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86781] = { id = 86781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Face the Past", description = "<Umbric scans the Eversong map with grave intent.>\n\nTranquillien was marked, as are a number of other locations. \n\n<Umbric stops, voice tightening.>\n\nWindrunner Village. It's marked.\n\nThe Twilight's Blade retreated to their base in Deatholme, but my home may be in peril. We must make sure my people in Windrunner Village are safe before pursuing them.", completion = "It seems all is well here... for now.", objectives = "Regroup in Windrunner Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86782] = { id = 86782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atrium Hospital", description = "The necrorays have been installed in the Atrium, and Hemet is seeing to them.\n\nHe has requested your presence.", completion = "Glad ye could come.\n\nLet's get started, eh?", objectives = "Meet Hemet Nesingwary in the Atrium.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86783] = { id = 86783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rays of Sunshine", description = "Right then. Let's get these rays into Eco-Dome: Primus to the north!", completion = "Ready for round two?", objectives = "Meet Hemet Nesingwary in Eco-Dome: Primus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86786] = { id = 86786, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Void Hunter", description = "The Void espouses all truths, {name}. And in none of them do I defeat Ramon'ta without some help.\n\nAnd here you are.\n\nMy quarry is a cosmic worm known as Ramon'ta the Insatiable. It started out small enough, but with each void entity it feasts upon, it grows, and its power grows along with it.\n\nIf we can defeat it, I can claim its power. Will you help me?", progress = "Wrap this up quickly, {class}. I have more important matters to attend to.", completion = "You've been helpful so far. And in return, I'll allow you to take part in making history on this discarded, broken corpse of a planet.", objectives = "Help Leona defeat the empowered cosmic worm and claim its power.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86800] = { id = 86800, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swipe 'Em" }
quests[86801] = { id = 86801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faceless Mask of Multitudes", description = "By our multitudes will the world drown and feed the hunger of our gods. Only by bathing in the blood of our foes may one rise to the exaltation of our masters and unleash their never ending multitudes for themself.", progress = "Place the Faceless Mask of Multitudes on the altar.", completion = "Satiated in the blood of multitudes now and forever. For our ranks will be endless and consume the world.", objectives = "Return the Faceless Mask of Multitudes to the altar within a Horrific Vision.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86805] = { id = 86805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hour of Need", description = "Turalyon is thinking like a battlefield captain and not like a leader! My people, the sin'dorei, have suffered much in these past few wars. How many must die in the name of his victory?\n\nPlease, {name}. Rescue any citizens you can and help guide them safely to the boats at the Silver Landing.\n\nEvery life saved is a victory for the blood elves.", progress = "The ships still have space for more! Rescue as many as you can.", completion = "The citizens have boarded the ships. They will soon reach the safety of Silvermoon." }
quests[86806] = { id = 86806, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Luminous Wings", description = "No! Xal'atath's Host has opened portals above the strait. Void creatures spill out and descend upon the refugee's ships. We have to safeguard the civilians!\n\nThose dragonhawks have been empowered by the Light. They should give you enough power to defeat the Void beasts and rescue the fleeing civilians.", progress = "The ships full of sin'dorei refugees are still in danger.", completion = "The ships have crossed the strait and the refugees have made it safely to Silvermoon. Thank you, {name}. You have done my people a great service.", objectives = "Take flight on the Empowered Dragonhawk, destroy 16 Devouring Host, and rescue 3 civilians in need.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86807] = { id = 86807, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gate", description = "The High Exarch commanded us to assemble with his Vanguard of Light and attack the Devouring Host. I do not regret my delay of that order, but he will have noticed my absence.\n\nWe should make haste and assemble with the others.", progress = "We shouldn't delay any longer.", completion = "Champion, I am glad to hear so many of the sin'dorei survived. Even though this was contrary to my orders to the Vanguard, you are not under my command. You acquitted yourself well. Arator did not.", objectives = "Assemble with the Vanguard of Light.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86808] = { id = 86808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Riddled Speaker", description = "Chief Vun'zarah knew little of Jan'alai, but he did know about their loa speaker.\n\nIf dey are still at de temple, then there is hope we can resurrect de loa.\n\n<Zul'jarra's hand tightens on her axe.>\n\nMakin' Akil'zon flee, woundin' Halazzi, sendin' Nalorakk into a rage, and killin' Jan'alai...\n\nMy grandfather and Malacrass have so much to pay for.", completion = "\"Purify yaself, and it will rise.\"\n\nI shoulda brought Zul'jan. He was always good with riddles.", objectives = "Meet Zul'jarra and Liadrin at the Temple of Jan'alai.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86809] = { id = 86809, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test of Conviction", description = "We got her attention. But now what?\n\nI know there is a trial. But Akil'zon is not givin' any hints on what it is.\n\nThink. Think. What did Kinduru teach me as a child? She is de loa of victory. But also of oaths and conviction.\n\nIf only we had made it to de top when I was a child, and I hadn't fallen...", completion = "<Zul'jarra's eyes are closed. She seems lost in thought.>\n\nDey were here all along. It was my grandfather's fault dey would not answer.\n\n<She nods her head and sighs.>\n\nMy grandfather broke dis. It is up to me to fix it. It is de only way to save my people.", objectives = "Prove yourself to Akil'zon with Zul'jarra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86810] = { id = 86810, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harvesting the Void", description = "To effectively counteract the void anomalies present here, we must obtain viable samples of the anomalies.\n\nSearch the area for containment vessels that hold developing anomalies, as well as the Unstable Oozelings created from the contamination.\n\nUse the collection device to make this process easier. Only living Oozelings will provide viable samples.", progress = "Have you collected the necessary samples?", completion = "I'm quite certain these samples will not be enough, but it is a good start!  Check back later I may have some more tasks.", objectives = "Collect 20 Anomaly Samples.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86811] = { id = 86811, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ethereal Eradication", description = "{name}! I have a mission for you. There is a contingent of Shadowguard ethereals to the northeast.\n\nThey appear to be looting the buildings, but that could change in a moment. The Vanguard cannot afford to be flanked as we advance. Take out their leader and decimate their forces while we engage the Host.", progress = "Have you completed the mission?", completion = "Excellent work, {name}. I knew I could count on you.", objectives = "Eliminate Norkonahl the Looter and 12 Shadowguard intruders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86820] = { id = 86820, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manaforge Omega: Dimensius Looms", objectives = "Defeat Dimensius in the Manaforge Omega raid.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86821] = { id = 86821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phase Diving: Unmoored and Unwell" }
quests[86822] = { id = 86822, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Final Relic", progress = "Good trip?", completion = "It seems we have more to do here than just finding a relic.\n\nThis area is overrun with a group that calls themselves the \"Dark Horde,\" and we are going to put a stop to their activities.", objectives = "Travel to the Burning Steppes and meet with the Sons of Lothar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86823] = { id = 86823, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Horde", description = "I once served under Blackhand, long ago. His son Rend was a sniveling fool: a coward who bolstered himself in that Spire after Doomhammer was defeated. He made deals with dragons, called himself Warchief, and proclaimed his Dark Horde the \"true\" Horde. Pah!\n\nThis Dark Horde embraces the ideals of a past long gone. Rend died years ago, but there are still orcs and ogres here who cling to the rotting husk that remains.\n\nIf they haven't seen the truth by now, there is little hope for them but death.", completion = "Perhaps, in the face of the death of their comrades, others will see sense as I did. At least those you killed won't dishonor themselves any longer.", objectives = "Kill 12 soldiers of the Dark Horde.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86824] = { id = 86824, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "None Left Standing", description = "The one thing worse than seeing this Dark Horde here is their banners.\n\nIt showcases their pride in this accursed mountain as a place of greatness--as a place for their horde to rise. In reality, this banner is little more than a defiled perversion of the ancestral Blackrock sigil.\n\nBurn down every one you find.", progress = "Got those banners dealt with, {name}?", completion = "I hope that this might demoralize some of these soldiers out of their misguided devotion to a failed cause.\n\nRegardless, I am glad those banners are not flying any longer.", objectives = "Burn 6 Dark Horde Banners.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86825] = { id = 86825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faithful Servant, Faithless Cause", description = "One of their lieutenants, Mar'kag, appears to be the one barking orders. His father, High Overlord Omokk, followed under Rend Blackhand's banner. Cruel, vicious... no surprise that his son follows in his footsteps.\n\nTaking Mar'kag down will spread chaos among the cowardly remnants of this Dark Horde and perhaps help them realize they are not as strong as they think.\n\nFaol also has us here to look for relic fragments. If Mar'kag has anything of note, bring it back.", progress = "Did you put a stop to Mar'kag, {name}?", completion = "As we defeat their leaders, the Dark Horde presence throughout the Burning Steppes will continue to splinter.\n\nMar'kag was the first to fall. This was a good first step.", objectives = "Defeat Mar'kag.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86826] = { id = 86826, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagosh the Scarred", description = "The Dark Horde may strut around inside the mountain, but an orc called Nagosh is the one rulin' this roost.\n\nHe barks orders, then charges straight into a fight. Rock-heads in command like that one are what gets everyone on all sides killed. \n\nI'd bet anything that numbskull claimed Faol's shiny relic. Keep an eye out. He may jump ye in the middle of a fight.", progress = "Did ye put a stop to Nagosh?", completion = "Did ye get Faol's relic?\n\nI hope that old priest knows what he's doing.", objectives = "Defeat Nagosh the Scarred.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86827] = { id = 86827, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Due Recognition", description = "Blackrock Mountain is where most of the Dark Horde has holed up. All their unit commanders adorn themselves with badges, struttin' around like they won the Second War. Shameful! But it gives me an idea.\n\nDefeat them and take their badges. Can't have new leaders that way--these blowhards like the pomp of command. Who wants the stress of leadership with no fancy badge to wear?\n\nHead on in there with Arator and keep 'em busy. Sky'reen an' I will support ye from the air.", progress = "Did ye get their badges, {name}?", completion = "That gave 'em a kick in the pants! \n\nSee if any of 'em volunteer to lead their warbands now, after that humiliation!", objectives = "Retrieve Stone Guard Badges from the Dark Horde in Blackrock Mountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86828] = { id = 86828, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Just a Troll's Bane", description = "As much as I'd love to keep harassing these Dark Horde grunts, we've found the relic piece that Faol wanted us to. We best be getting on.\n\nDanath went looking for the last piece of the relic. You go find him, and I'll tell the mad bishop that his plan is nearly complete. Find me at Lothar's Statue when yer done.", completion = "{name}, Arator--good to see you. I believe I have a solution to our problem.", objectives = "Find Danath Trollbane.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86829] = { id = 86829, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Landmark Moment", completion = "These fragments you've been recovering might be the most important relics of our journey, {name}.", objectives = "Meet the Sons of Lothar at Lothar's Statue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86830] = { id = 86830, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A True Horde of Dark Horde", completion = "You killed many of them, but I watched even more run away. \n\nLet's hope they never return.", objectives = "Defeat 12 Dark Horde troops and 3 Dark Horde Sergeants.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86831] = { id = 86831, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warriors Without a Warlord", description = "Despite our work in the area, the Dark Horde continues to battle. Their leader is there, in Blackrock Stronghold, likely bolstering their spirits. \n\nTake them out. Once we do, I suspect this Dark Horde will come to nothing, with much less bloodshed.\n\nAnd Faol thinks there may be a fragment of the relic he's looking for in there. Recover that as well!", progress = "Have you taken them out?", completion = "Excellent, {name}! I believe this will save many lives across the region. With no warlord to rally them, the Dark Horde should fall apart.", objectives = "Enter Blackrock Stronghold and take out the leader of the Dark Horde.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86832] = { id = 86832, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Forge", completion = "We certainly did some good in the Burning Steppes, {name}, and recovered the fragments of Turalyon's shield.\n\nArator seems excited to see it reforged.", objectives = "Return to Silvermoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86833] = { id = 86833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bulwark Remade", progress = "Thank you for helping me with this, {name}.", completion = "{name}, that did not go as I hoped, to say the least.\n\nI'd hoped he would be able to see... to accept that he could still change.\n\nBut it doesn't look like he's open to that--at least, not now.", objectives = "Help Arator reforge his father's shield.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86834] = { id = 86834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voidborn Banishing", description = "The Devouring Host are composed of horrors from the depths of the Void, but they are still an army, with soldiers and leaders. Amongst that sea of void walkers, I notice there are singular creatures.\n\nWhether commander or mascot to the Host, removing them from the battlefield will help to break their lines.", completion = "Going behind our lines was reckless! Was this Arator's idea? He has been so headstrong lately.\n\nSorry, {name}. I shouldn't air this family business. I will admit that your actions have aided the Vanguard of Light in this battle.", objectives = "Slay Latrunculon, Blightclaw, and The Wasting.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86835] = { id = 86835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Regroup!", description = "We've stabilized most of the city and saved as many as we could, but our job isn't over.\n\nLocus-Walker must still be out there looking for the enemy commander. We've already searched over most of the city, so he must be in the one place we've not yet looked.\n\nCome, {name}. Meet me at Myza's Oasis.", completion = "I found our quarry, but unfortunately not before they broke into this shelter.", objectives = "Locate Locus-Walker within Tazavesh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86836] = { id = 86836, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunter Awaits", description = "I have warned Orweyna of the dangers and madness that lay within the Rift of Aln, but she believes it is her only path forward. I envy her faith.\n\nSomeone can help show her the way: the Shul'ka. The Hunters of Shadows. They have sacrificed everything to protect the haranir from the effects of the rift.\n\nI will let one know that you need help. You will find him in the Vale of Mists.", completion = "I have given up my connection to the goddess to protect my people from the dangers of the Rift of Aln. I do not believe anyone should ever go there without knowing what you risk. Haranir will succumb and die without protection.", objectives = "Find Orweyna and the Shul'ka in the Vale of Mists.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86837] = { id = 86837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet at the Sunwell", description = "I have been tasked with bolstering the Vanguard of Light that empower the Sunwell. I need your help, though not just for that simple task.\n\nOur mutual friend, Arator, is... stuck. Stuck in his grief and anger over that tragic conflict between him and his father.\n\nI'm just an old priest that's been raised from the dead, but I've found that a quest is just the thing to set a young paladin back on the right path.\n\nWould you help?", completion = "Nnnghhh... It is so painfully bright here, don't you think? \n\nAhh, you were able to convince him. Thank you.", objectives = "Ask Arator to meet Faol at the Sunwell.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86838] = { id = 86838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renewal for the Weary", description = "The Vanguard of Light are maintaining a difficult ritual at the Sunwell. It requires focus, discipline, and is quite exhausting.\n\nTake my staff. I've had it since I was Archbishop in Stormwind. It is meaningful to me and my faith. The Light responds to meaning and intention. It should renew the Vanguard's spirits so they can maintain the ritual a while longer.\n\nI can't approach any closer to the Sunwell, so you will have to do this for me.", completion = "I had hoped that seeing the rest of the Vanguard focused on the Sunwell, it would give him a goal that was bigger than his pain and lead him away from his anger. Instead, he belittles my solution.\n\nThank you, {name}, for doing it in his stead. It was necessary to keep the Voidstorm at bay.", objectives = "Restore the Light to 10 weary channelers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86839] = { id = 86839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relics of Light's Hope", description = "The holy power in my staff has been spent. Forty years of fervent prayers drained away in a few minutes. It was for a good cause, and my staff will recover in time.\n\nThere are other relics, like my staff, that were important to paladins and priests. Light's Hope Chapel has many such relics stored there.\n\nArator trained there as well. Perhaps the solution to his pain could also be found within.", completion = "Welcome to Light's Hope, {name}. \n\nMost of the paladins that defended these grounds were called by the Light. I've had to reach out to the Ebon Blade for support, or the Scourge would have overrun this holy place.", objectives = "Meet Lord Maxwell Tyrosus at Light's Hope Chapel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86840] = { id = 86840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flickering Hope", progress = "We can't hold back the undead forever, {name}.", completion = "Thank you, {name}. You've thinned their ranks enough that we'll be able to maintain the defenses, with the help we have from our... allies.\n\nNow, Faol has told me about your need for relics.", objectives = "Kill Scourge forces around Light's Hope Chapel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86841] = { id = 86841, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relics of Paladins Past", description = "Alonsus tells me you're looking for relics of holy power, to sustain those performing the ritual holding the Void at bay.\n\nNow that you've beaten back the Scourge, you and Arator are certainly welcome to enter the Sanctum of Light and use what we have for the cause.", progress = "Countless great heroes are interred under the chapel, {name}. \n\nHopefully their relics can be of aid to those at the Sunwell.", completion = "I trust you found what you needed, {name}?", objectives = "Gather 5 relics from the Sanctum of Light.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86842] = { id = 86842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scarlet Power", description = "These artifacts will help sustain the Vanguard, but they are not enough. I know of a place nearby that would have the rest we need, but... given Arator's state of mind, I'm hesitant to go there.\n\nHmph... No sense in avoiding it. We must all face up to the fact that Scarlet Crusade calls upon the power of the Light, and has for decades.", progress = "When it comes to reclaiming relics of the Light from the Scarlet Crusade, there's no better time than now, {name}.", completion = "Here we are. Let's deal with these Scarlets.", objectives = "Meet Alonsus Faol at Scarlet Monastery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86843] = { id = 86843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Light Miswielded", progress = "Have you dealt with the Scarlet threat, {name}?", completion = "Excellent work.\n\nPerhaps one day, the Scarlet Monastery can be a place that truly serves the Light, but for now our time is limited and our focus must remain on the Sunwell.", objectives = "Defeat Scarlet Crusade members.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86844] = { id = 86844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Light Repurposed", description = "Leaders of the Crusade have channeled the Light through their weapons every day for years. \n\nWhile their goals and actions are reprehensible to us, their weapons are no less useful than my own staff, especially in such a time of need.\n\nAs you go through the Scarlet Halls, whenever you find a leader, defeat them and bring back their weapon. We will put it to a righteous use: to aid the Sunwell.", progress = "What artifacts have you found here, {name}?", completion = "These weapons of the Light shall serve a much greater purpose from this day forward.\n\nI hope that may be true as well for Aelyse--the Scarlet champion Arator showed mercy to.\n\nI told her to begin by surrendering herself to Calia Menethil at the Sunwell.", objectives = "Recover Meyer's Rod of Castigation, Aelyse's Gleaming Falchion, and Benthar's Scarlet Spire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86845] = { id = 86845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sunwalker Path", description = "I think I have failed Arator. In my attempt to steady him after the incident with his father, I may have shattered his faith with uncomfortable truths of the Light.\n\nI would like to consult with the wisest person I know, Sunwalker Dezco. I did not see him with the Vanguard. Tyrosus told me he may be in Hammerfall providing aid to the displaced.", completion = "An'she has guided you to us, {name}. Care to join us in our work?", objectives = "Meet with Sunwalker Dezco in Hammerfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86846] = { id = 86846, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Resupplying Our Suppliers", progress = "Have you distributed the supplies, {name}?", completion = "Excellent! This will help the people of Hammerfall help themselves.", objectives = "Aid the people of Hammerfall in their recovery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86848] = { id = 86848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Light's Arsenal", description = "The armory here stores legendary weapons and artifacts, blessed with the power of the Light due to their proximity to the Sunwell.\n\nWhile we are pinned down by the Host, the ethereals are looting these treasures.\n\n{name}, secure these holy artifacts. They are our best weapons against the Void. Use them to cut down these invaders if you have the need.", progress = "Have you secured our artifacts?", completion = "Were they just here to loot us? Or did they have some reason to seek out weapons of the Light? \n\nI'll save that speculation for later. The Vanguard can use these weapons now. With them, we will push this Devouring Host off Quel'Danas!", objectives = "Collect 7 Legendary Weapons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86849] = { id = 86849, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrath Unleashed", description = "{name}, the time has come! We push these fiends to Sun's Reach Harbor! We drive them back into their accursed void portal and drive them from these sacred shores!\n\nFor the Light! For Azeroth!", progress = "Don't stop until we drive them from these shores!", completion = "By the Light! We cannot win this battle. Our only hope lies in the Sunwell!", objectives = "Join the charge of the Vanguard of Light.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86850] = { id = 86850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Broken Sun", description = "We need to fall back! This is not a battle that we can win. Not like this.\n\nBut there is still hope! The Sunwell. It brought the Vanguard of Light here to defend it. It brought you, {name}. Fall back to the Sunwell chamber and defend it for as long as we can.\n\nI have faith the Light did not intend for us to lose this day.", completion = "Thank the Light. Everyone from the Vanguard that survived is in the Sunwell chamber. Now that you are here, we can begin.", objectives = "Meet Liadrin at the entrance to the Sunwell.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86851] = { id = 86851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Foundation of Aln", description = "The presence of the goddess reverberates through everything in the Rift of Aln. The voice is too powerful for haranir to resist. In mere minutes, one of our flock would be lost forever.\n\nThere are, however, ways to protect oneself for a short time. Kill the rejects that crawl up from the rift and gather the Alndust from which they are created. I can show Orweyna how to craft a short-term solution for entering the rift.", progress = "I will let your young companion know what to do with the Alndust.", completion = "My hands tingle where the Alndust touches. A curious feeling... not unwelcome.\n\nThe honored Shul'ka told me how to manipulate the Alndust to protect haranir in the rift. It seemed difficult, but with its magic swelling in me, I feel that it should be doable.", objectives = "Collect 6 alndust from Rift creatures in the Vale of Mists.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86852] = { id = 86852, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Light's Last Stand", description = "Our attempts to fight Xal'atath's Devouring Host have failed. Our only hope is to call upon the Light once more and trust that there was a reason it brought this Vanguard together. \n\n{name}, you and Arator need to protect the Sunwell from the Devouring Host. With so few of us left, we cannot spare any more defenders.\n\nOur faith in the Light will save us.", completion = "May the Light bless and protect you, {name}. Your defense of the Sunwell chamber made this miracle possible.\n\nWe have not beaten Xal'atath, but we have forestalled the invasion of her Devouring Host. We now have the time to catch our breath and discover what we must do to defeat her.", objectives = "Defend the Sunwell from the attacking forces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86853] = { id = 86853, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sparks of War: Undermine", description = "Investigate the Undermine! Reports are coming in about a growing conflict in the area, go and check it out.", progress = "Go off and complete your investigation.", completion = "YOU SURVIVED? And with all your limbs no less. Well done.", objectives = "Collect 100 Sparks of War in Undermine, while in War Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86855] = { id = 86855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Consequences of Our Duty", description = "You must see with your own eyes the effects that the Rift of Aln can have on any haranir. Even those who stand guard over the border are oft affected by its call.\n\nTake this. I use it as an emergency salve to help those who are stricken of the dangers of Aln. Patrol these lands and give aid to those who need it. Perhaps then you will understand the gravity of what you seek to do.", progress = "I did not know that these castoffs from the rift could affect us so much...", completion = "It is sobering to see the effects of the rift on my peoples. But Amarakk's interference has given me unintended hope.\n\nI must go into the rift to search for Hagar's answer, and with the Shul'ka's help, I may even survive this ordeal.", objectives = "Heal 5 Wounded Guardians in the Vale of Mists.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86856] = { id = 86856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dampening the Call", progress = "The process sounded simple enough--well within my abilities. But I appreciate your presence here to ground me.", completion = "I cannot hear the voice of the goddess.\n\nI hate it.\n\nHow does Amarakk live like this?", objectives = "Help Orweyna create the Alndust Filter at the Vale of Mists.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86857] = { id = 86857, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Descent into the Rift", description = "With this, I will be able to venture down into the Rift of Aln. I will not have long, so we should not dawdle.\n\nLet us find Amarakk and gain his help.", completion = "That manifestation is one of the purest forms of Aln madness that resides here. My ward will distract it only for so long. We must move quickly.", objectives = "Find the Wards of the Shul'ka in the Rift of Aln to find Amarakk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86858] = { id = 86858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Madness Roots Deep", description = "I found you while I was in the middle of one of my duties. Someone has spent too long within the rift and has fallen prey to the call of the goddess. I must rescue him and send him back to where he belongs.\n\nHelp me with this task, and I will help you.", progress = "We can save him!", completion = "Another soul saved.\n\nThis is why I do this, {name}. All my sacrifices, shutting myself from the voice of the goddess, is worth it for each soul I rescue from the grasp of the rift.", objectives = "Defeat On'hiea in the Rift of Aln.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86859] = { id = 86859, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grinding Out a Solution", description = "I have been pondering what Hagar could have meant from the moment Orweyna mentioned an answer to your problems. There are no mystical fountains--no weapons. Everything in the rift is created from the same source: Alndust, the distillation of the influence of the goddess. If we hunt a large manifestation, you will have the power of creation in its purest form.\n\nWe cannot defeat it without help. Search the rift and look for fungi large enough to cultivate. I can use them to give us an edge.", progress = "Any advantage that we can have against the manifestation will give us a better chance to survive.", completion = "We might have a chance with this. I'll be able to coat my weapons with this and craft a powerful poison.", objectives = "Find 5 Alngrown Fungus in the Rift of Aln.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86860] = { id = 86860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Before They Grow", description = "Within every creature that roams the Rift of Aln thrums a gathering of the foundation of the goddess's influence. This Alndust yearns to merge with others of its ilk. Part of my duties as the Shul'ka is to make sure to keep the number of large manifestations low so they do not overwhelm the Den.\n\nIt is easiest to do that while they are small.\n\nTake this spear. You may use it to shatter the smaller creatures down to... trivial sizes.", completion = "Well done.", objectives = "Use Amarakk's Influence to defeat Aln Mites and creatures in the Rift of Aln.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86861] = { id = 86861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herding Manifestations", description = "We are preparing to fight a giant manifestation. Let me emphasize this again. We must fight just one.\n\nIf we fight two at a time, we would have no chance of survival. Place these wards around the rift to draw the others away. They will not last long... but we will need every advantage we can gain.", progress = "These wars are a creation of my own making. They attack the larger creatures toward them by mimicking their reaction to food.", completion = "That must be enough.", objectives = "Place 3 Wards around the Rift of Aln.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86862] = { id = 86862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Greater They Aln", description = "We have one chance at this only.\n\nI pray we have prepared enough.", progress = "The power of the Rift of Aln is beyond mortal comprehension. What we are doing is simply borrowing some of it for a brief moment.", completion = "I thought I would never see this with my own eyes... and yet here we are.\n\nMake this worth it.", objectives = "Defeat the Aln Manifestation and gather its components in the Rift of Aln.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86864] = { id = 86864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Watch the Den", description = "Finally, we have a moment to breathe. This is where we feel closest to the goddess--we are below the Cradle where she used to rest.\n\nThe elders will not allow us to use any of the Alndust they have gathered over the centuries. They see only what the goddess asked of us before, not what her world needs now.\n\nAlndust is rare, but there are ways to get it. Ask around. I will check... elsewhere.", progress = "I hope that you will be able to rest here. You must know how to navigate this place.", completion = "In the end, we must figure this out for ourselves.", objectives = "Speak to the Innkeeper, Renown Quartermaster, and the Flight Master at the Den.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86865] = { id = 86865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Search of the Problem", description = "We did what Hagar asked us to do. The next step will be to test this on something--or someone--afflicted with the Lightbloom.\n\nIt may be difficult to find the Lightbloom in enough quantities in Harandar, but I believe we will find what we need at Har'alnor. I will meet you there!", completion = "We have left our homes. We will return.", objectives = "Meet Orweyna at Har'alnor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86866] = { id = 86866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Can We Heal This?", description = "The rutaani have escaped their nearby villages to Har'alnor. The guards have told me that some of them have been afflicted with the Lightbloom, yet have not succumbed to its effects.\n\nThis may be our best opportunity to test the Alndust's powers. Time is of the essence!", progress = "This is it, {name}. The moment of truth. Do we have an answer for the problems on Azeroth?", completion = "The Alndust may not be able to recover someone who has fully fallen to the Lightbloom, but it should be able to inoculate those from further corruption. That must be enough.", objectives = "Use the Greater Alndust on the Afflicted Rutaani at Har'alnor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86867] = { id = 86867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Lightbloom", description = "We've gathered the haranir we have available and distributed the Alndust. We have everything we need, but they need to be able to safely enter the area. Scouts have told us that the creatures spreading the Lightbloom are protected by a shield. We must stop them. We will also need to thin their numbers.\n\nGet on the petalwing, {name}, and let's clear the way.", progress = "We ride together!", completion = "Now we can begin.", objectives = "Ride on the Petalwing, destroy the shields protecting 4 Lightbloom Spreaders, and defeat Lightbloom creatures in the Blinding Bloom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86868] = { id = 86868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goodwill Tour", description = "The situation here is far worse than I imagined.\n\nThe Twilight's Blade and their leader, Mor'duun, have completely overrun this city.\n\nWe will use this opportunity to show the Amani how efficient we are at eliminating forces of the Void. Perhaps that will help convince them to stall hostilities between our people... at least until the current threat has passed.", completion = "Zul'jarra has noticed your prowess in battle.\n\nGood.\n\nLet us continue demonstrating our usefulness. If they push us out of their lands now, we'll have no way to keep an eye on the Twilight's Blade until they're flooding through the gates into Eversong.", objectives = "Kill 10 Invading Shadows while traveling deeper into the city of Atal'Aman.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86869] = { id = 86869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phase Diving: Shan'dorah Saboteurs" }
quests[86872] = { id = 86872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phase Diving: Experimental Extermination" }
quests[86874] = { id = 86874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Culling the Light" }
quests[86877] = { id = 86877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Righteous Pruning", description = "This is a threat that could destroy all of Harandar if left unchecked. That's why we will pull this out at the root.\n\nThe ruutani who did not have the time to escape this place must be fully corrupted by now. Unfortunate, but it makes our plan of attack simple. Their leaders must be spreading the Lightbloom. We must strike them down.", progress = "If these leaders are allowed to thrive, they will gather more forces to the Lightbloom. We can't allow that to happen.", completion = "I wish we could save everyone, but...\n\nA gruesome but necessary task.", objectives = "Kill 4 Lightblinded Sap Weavers in the Blinding Bloom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86880] = { id = 86880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Beloved, Returned", description = "The haranir had a presence by the roots of Shaladrassil, as a sign of goodwill with the cultures that live within our home. When the guards retreated, they left some of our treasured mementos and artifacts.\n\nSince the spread of the Lightbloom has been greater than I ever expected, I do not know when we'll be able to come back. Let's find those artifacts in the Blinding Bloom and bring them home.", progress = "It would be good to bring some of these items back in our hands.", completion = "These artifacts pale in importance to the lives of those involved here... but it is good to have them back.", objectives = "Recover 6 Haranir Artifacts in the Blinding Bloom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86881] = { id = 86881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "At the Root", description = "The growths that help them spread the Lightbloom so quickly should be vulnerable after your attack from the air, but we still need to destroy them. Return to the Blinding Bloom and uproot the spreaders before they can recover from our attack.", progress = "We need to stop the spread of the Lightbloom, lest it take over all of Harandar.", completion = "I pray this will help us all.", objectives = "Destroy the Lightbloom Spreaders in the Blinding Bloom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86882] = { id = 86882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alndust in Right Hands", progress = "I know that my people are ready to step up to the challenge.", completion = "This is so much more than what the Rootwarden said. How has the Lightbloom spread so much, and so quickly?", objectives = "Give Alndust to 5 haranir around Har'alnor and the Blinding Bloom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86883] = { id = 86883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Frenzied March", description = "Halduron's news is dire. If the Lightbloom is frenzying on the surface, then the danger has grown far more quickly than we were prepared to reckon with.\n\nWe must make for Eversong at once. I will stand against any threat to Aln'hara's creation, be it here or in the world above... and I will do it alone, if I must.", completion = "To think that while we toiled below, the Lightbloom would spread so aggressively in Eversong.\n\nDamn it all! Every victory we win reveals rising danger.", objectives = "Return to Eversong Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86884] = { id = 86884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cull and Burn", description = "Simply culling these creatures is not sufficient. If their bodies are left unattended, the Light will seep from their remains and spread through the soil to the surrounding foliage.\n\nWe must take more drastic measures. Gather the bones of the creatures you slay. If we burn them, perhaps we can prevent their further spread through the roots of this forest.", progress = "Do not delay. The longer we wait to cull this growth, the more of this forest the sin'dorei will lose.", completion = "It is a shame to see something born of Harandar wreaking such havoc on a place like this. These roots may not cradle Aln'hara, but they grow toward her all the same.", objectives = "Collect 10 Corrupted Bones from Lightbloom-Infested wildlife.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86885] = { id = 86885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stem the Tides", description = "When the Farstriders first discovered the Lightbloom, we thought it to be merely an aesthetic change--a small quirk of the Sunwell's influence. Would that we knew then what we know now.\n\nThese Light-frenzied rootways must lead all the way back to Harandar. If we don't close them, it won't matter how many of these damned things I bring down. Close the rootways and we might have a fighting chance.", progress = "What are you waiting for? Every moment that passes, more of those things filter through. Our odds are scant enough as it is.", completion = "Damn it all. For every rootway you torch, two more crop up elsewhere. It's like they're self-perpetuating, spreading in the span of moments.\n\nI don't think we can solve this with arrows and magic, even with Orweyna's help. We don't have enough Alndust, nor enough haranir to prevent the spread of this frenzy.", objectives = "Burn 5 Lightfrenzy Portalways.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86887] = { id = 86887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expeditious Retreat", description = "I have a way to stop the Lightbloom from spreading further through the forest, but it isn't exactly a delicate touch. Normally, I'd never dream of resorting to a controlled burn in such a healthy portion of Eversong... but the frenzy is spreading too quickly, and we are running out of options.\n\nI've sounded the retreat to my Farstriders, but some of them haven't responded. I need you to find any rangers in particularly sticky situations, and lend your aid in securing their escape.", progress = "We're short on time, {name}. I can't execute my plan if we have Farstriders still in the field.", completion = "Most of the Farstriders have retreated to our position. Those that remain are prepared to slip away once the ritual begins.\n\nWe're out of time. It's now or never.", objectives = "Rescue 3 Beleaguered Farstriders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86890] = { id = 86890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tell the People What You Have Seen", progress = "I only pray that they are more receptive to the truth this time around.", completion = "Azeroth needs our help. I will not stand idly by while she is overwhelmed.\n\nI know you will not, either.", objectives = "Return to the Den to speak to the Elders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86891] = { id = 86891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Last Resort", description = "With our ground forces pulled back, our position will be overwhelmed in a matter of minutes. It's time to execute our gambit.\n\nRommath and the Magisters have provided us a mana gem that can be used to overload Lash'ra's runestones. Take it, and infuse the stones with the mana contained therein. That will set the stage for the Magisters' ritual: to detonate the runestones and burn the entirety of Lash'ra to the ground.\n\nWe just have to hope the Lightbloom cannot survive in an inferno.", completion = "We've done all we can.\n\nNow all that's left is to defend the Magisters, and hope that this is enough to stop the frenzy from spreading any farther.", objectives = "Overload 3 Phoenixfire Runestones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86892] = { id = 86892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Survive", description = "Our retreat to safer ground has not gone unnoticed. The rutaani mark us at every turn, and now they mean to cross the river.\n\nWe have to buy Rommath and the Magisters as much time as we can. If we fail here, the whole of Eversong could be lost.\n\nStand tall. Do not falter. And do your best not to die.", progress = "We do not know when the frenzy will push past the lakeshore and encroach upon our position. Better to have Rommath start the ritual sooner rather than later.", completion = "I... I cannot believe it. My kin on the surface, standing shoulder to shoulder with surface-dwellers, and wielding the magics of Aln...\n\n<Orweyna sets her jaw and flashes you a smile.>\n\nBut we do not have time for sentiment. We must bring Ruia to justice, and end this frenzy.", objectives = "Survive the Lightbloom onslaught.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[86894] = { id = 86894, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gift of Aln'hara", description = "Ruia has always been a zealous advocate, but this behavior is beyond the pale. The Lightbloom must be affecting him, driving him to these dangerous lengths.\n\nBut we do not have to be like him. This forest need not fall to the bloom like Shaladrassil's roots did.\n\nThe Hara'ti brought enough Alndust to bolster our allies against corruption, and prevent the frenzy from spreading further. Together, you and I shall spread Aln'hara's gift across the forest. This frenzy shall advance no further.", completion = "The haranir are always mighty. But with the goddess's gift shining upon us, we are unstoppable.", objectives = "Use the Alndust to combat the Lightbloom frenzy in Lightbloom Lash'ra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
